INSERT INTO `project` (`id`, `projectnaam`, `projectleider`, `klant`, `prio`, `projectcoach`, `telefoonnummer`, `emailklant`, `projectleden`, `initiatieleider`, `project_status`, `opmerkingen`, `opleiding`, `administratienummer`, `bewerkt_door`, `bewerkt_datum`) VALUES
(28, 'Duurzame Proeftuinen', 'Damian van der Sluis', 'Eef De Graaf', 'Normaal', 'Cees-Jan Berman', '+31 6 154 541 74', 'eefdegraaffilm@gmail.com', 'Damian van der sluis', 'Jeffrey Scheffers', 'Bezig', 'Hoi RenÃ©,\r\nVanmorgen hebben Hendrik-Jan en Jean (in zijn rol als proceseiegenaar Duurzaam Scalda) kennisgemaakt met Eef de Graaf.\r\nEef is filmmaker. Zij heeft een documentaire gemaakt over duurzaamheidsprojecten in de Nederlandse delta\'s, en beweeg zich daarmee in dezelfde netwerken als Scalda.\r\nAls volgende stap wil ze haar filmmateriaal inzetten voor educatieve doeleinden. Dit is voor haar reden om contact te zoeken met Scalda.\r\nJe kunt haar werk hier zien: \r\nhttps://www.eefdegraaf.com/nieuwe-film\r\nIn het gesprek vanmorgen, vertelde Eef dat ze voor een relatie op zoek is naar studenten die een app kunnen bouwen, waarmee allerlei informatie over een natuurgebied ontsloten kan worden.\r\nIk weet niet of er een match is tussen de vraag van Eef en wat wij vanuit Scalda kunnen bieden, maar zou Ã¨Ã¨n van jouw mensen eens met haar willen contacten?\r\nHartelijke groet,\r\nKarin\r\n\r\n28 sep 2021: tel gesprek - Tijd begin oktober.\r\n\r\n2021-28-09: contact gehad, heeft niks opgeleverd. niet veel bereikt, 4 afbeeldingen met paar verwijzingen?  Gerhard gaat bellen.\r\n\r\n2021-10-05: Jeffrey en Tristan. Contact gehad met Eef. Morgen een meeting met haar. Dan kunnen ze het hebben over vormgeving etc. De dynamische kaart bijna af. Deze week komen meeste dingen af. Voor 1 okt had ze niet veel tijd voor project, hierna zal dit beter zijn volgens de klant (zegt Gerhard). Hij wilt aanduiden om beter contact te krijgen. Michael zegt zorg dat je afspraken maakt tijdens de meeting morgen, zodat je zelf goed vooruit kan.\r\n\r\n2021-10-12: meeting van vorige week verzet naar 2021-10-13.\r\n\r\n2021-10-19: Drastische meeting woensdag gehad, deze was chaotisch. Volgende meeting in de week van 8 november om het opniew te proberen.\r\n\r\n2021-11-02: TO moest nog afgemaakt worden maar zijn begonnen aan realisatie.\r\n\r\n2021-11-09: Jeffrey. Vadnaag reactie gehad. Vrijdag zitten ze samen voor acceptatie test.\r\n\r\n2021-11-30: documentatie is nog niet goedgekeurt door klant omdat ze nog niet hebben gereageert, maar ze werken wel alvast door.\r\n\r\n2021-11-07: realisatie klaar, codereview moet gedaan worden. gesprek met klant aankomende donderdag.\r\n\r\n2021-12-16: Ik ben bezig met ontwerp fase.\r\n\r\n2022-01-11: De styling moet op de app worden toegepast.\r\n\r\n2022-01-18: Gesprek ging goed. Volgende sprint is de laatste. Hosting gebeurd buiten de 10 sprints. Donderdag volgende meeting.\r\n\r\n2022-01-25: klant tevreden met oplevering, volgende week laatste sprint. hosting word mee genomen als het kan anders niet.\r\n\r\n2022-02-01: klantgesprek aankomende vrijdag.\r\n\r\n15-02-2022: Oplevering word naar volgende week verzet. Tristan is bezig met implementatie, gaat dit met Gerhard bespreken.\r\n\r\n22-02-2022: gister gesprek met de klant, acceptatie test gehad. is nu feedback aan het verbeteren\r\n\r\n03-09-2022: tristan heeft meeting gehad met de klant. Acceptatie test gedaan paar verbeterpuntjes. Deze sprint documentatie en feedback verwerkt.\r\n\r\n22-03-2022: Gaat goed. Ze zijn bezig met afronden, implenteren. Ze is onderzoek naar test personen. Intern testen moet ook nog gebeuren. Deadline testpersonen is vrijdag voor Eef. \r\n\r\n29-03-2022: Hij gaat implementeren. Hij moet een meeting met eef inplannen, dan gaan ze hosten. Hij heeft er al onderzoek naar gedaan. Kosten is ook al over nagedacht, dit staat in het implementatie plan. Volgende week gaat hij zijn nieuwe project starten met Norah. Hij moet zijn planning aanpassen en updaten in teams. \r\n\r\n18-10-2022: hij gaat binnekort samenzitten met de klant om eventueel alle zaken verder op te pakken. Hij is nu opzoek naar iemand die bij dit project kan aansluiten. De klant is op zoek naar een vast contact persoon. Daarom dat hij dit verder oppakt. \r\n\r\n29-11-2022 : De website staat online, door de wifi die niet werkt kan hij er nu momenteel niet verder aan werken. Het domein van Kevin moet worden verandert omdat hij nog geen docent is. ', 'Software', 'EX-2021-03', 'Dylan', '29/11/2022 11:46'),
(29, 'Feijter werkplaats inspectie app', 'Jaimy Zegers', 'De Feijter forklift services', 'Normaal', 'Cees-Jan Berman', '-', '-', 'Jaimy Zegers', 'Jaimy Zegers', 'Factuur', '2021-28-09: ligt op schema, vandaag is documentatie goedgekeurd. Jaimi kan morgen full time op dit project helpen. geen problemen voor de rest.\r\n\r\n2021-10-05: Hij is bezig met realisatie. Donderdag word meeting ingepland. Hij loopt vast met wordpress. De delete update moet nog gemaakt worden en is lastig.\r\n\r\n2021-10-12: dit word 2021-10-15 opgelevert\r\n\r\n2021-10-19: Korben. 15de is het opgeleverd, ging goed. Alles werkte. 1 functie stond er nog niet in, nu wel. Verder is ze akkoord gegaan, dus kan hij verder.\r\n\r\n2021-11-02: jaimy is de niewe ontwikkelmethode aan het ontdekken en yari moet nog 1 diagram opniew maken.\r\n\r\n2021-11-09: Korben. Is klaar met functies voor het kopje. Als alles werkt kan hij aan het thema werken. De vertraging van vorige keer is hij mee bezig, diagram is al af.\r\n\r\n2021-11-30: Is bezig met documentatie, moest veel opnieuw doen, user storyï¿½s, etc. Jaimy ging verder met de app. Wss kan hij de documentatie vandaag inleveren.\r\n\r\n2021-12-07: gisteren een meeting met de klant, bijna een implementatieplan af had. Deze wordt doorgezet naar de volgende sprint. Korben hoop dat hij hier zo snel mogelijk mee aan de slag kan. Volgende week maandag gaat hij met de klant over het ontwikkelingsproject praten. Korben geeft aan dat de klant het begrip van het betalen van het eindproduct en voor de sprint betaald snapt.\r\n\r\n2021-12-16: In communicatie met Progression over implementatie; Applicatie moet door andere partij gehost worden\r\n\r\n2022-01-11: Ze zijn een hosting service gaan het zoeken. Hij probeert alles deze week af te ronden.\r\n\r\n2022-01-19: alleen nog hosting vinden, als hij niks voor vrijdag vind gaan we inschieten\r\n\r\n2022-02-01: hij gaat kijken of hij vanavond die acceptatietest kan doen met zijn vader\r\n\r\n2022-02-08: hij zal navragen aan progression waneer hij de testomgeving kan afronden. in de tusstijd zal er een code review plaats vinden.\r\n\r\n15-02-2022: hij krijgt vandaag de gegevens voor het intergreren binnen. dit gaat hij bekijken, hij zal bellen als het niet duidelijk of hij naar locatie moete komen. zo ja? dan zal hij dit meteen in plannen.\r\n\r\n22-02-2022: Korben heeft vandaag pas de gegevens gekregen, ze hebben kleine veranderingen gedaan in de tussentijd. hij zal een datum inplannen om naar feijter te gaan.\r\n\r\n02-09-2022: Voor de vakantie geÃ¯mplementeerd. Twee dingen die niet werkten; telefoonnummer veld, met niet werkende plug in er in gezet. LMRA werkt ook niet. Er moeten nog 4 userstories zijn voor deze sprint. Hij heeft de globale planning af hij moet nu nog alleen plan van aanpak even maken. hij heeft alleen implementatie test gedaan en geen acceptatie test gedaan. \r\n\r\n15-03-2022: Realisatie is goed op weg. User story is ook klaar als de andere klaar is. Jaimy weet nog niet waar alles word opgeslagen. Jaimy moest nog iets vragen aan Tristan over data base.  Er is nu een test server, lma werkte nog niet. Ticket staat nog open van Korben. Hij heeft aan Gerhard aangegeven dat het eigenlijk geen Ticket was. ??\r\n\r\n22-03-2022: De admin kant is klaar. Eerste code review moet geregeld worden. Jaimy moet nog veel doen aan mobiele kant. Als hij er hard aan werkt is het deze week af. Implementeren moet niet meer op locatie zijn, hij doet dit thuis. Korben is bezig met test documentatie. Hij heeft nog niemand gevonden om te testen. Hij kan het aan Damien vragen. Rick en Korben gaan van elkaar testen.\r\n\r\n29-03-2022:  Korben is begonnen aan de app. Het lijkt dat alle functionaliteiten werken. Hij moet het fatsoenlijk op de mobiel laten werken. Het is de bedoeling dat ze deze sprint afronden. Er is nog geen echte hosting, alleen een test. Hij heeft een mogelijke host gevonden. Ruben zegt dat er echt iets aan veranderd moet worden omdat hij al sinds vorige sprint zoekt naar hosting. Minstens eind van de week wilt Ruben een definitieve hosting van Korben.  Het implementeren lukt alsmaar niet thuis. Gister lukte het ook niet bij Feyter zelf. Vandaag fixt hij afbeeldingen, als dat af is gaat hij implementeren. \r\n\r\n05-04-2022: Hij ligt niet op schema. Jaimy en hij hebben besloten dat Korben van het project gaat en Jaimy erop blijft. Dan kan Korben verder aan een ander project. Ze hebben nog geen documentatie gemaakt. Jaimy was bezig met Sam dus kon hij dit niet doen. \r\nHij moet nog een code review doen voor alles, hij moet nog iemand vinden. Hij heeft het aan Sander gevraagd. \r\n\r\n12-04-2022: Korben is nogsteeds bezig met de code. Hij is nu in realisatie fase. Loopt op schema.\r\n\r\n19-04-2022: Er moeten nog een paar dingen gedaan worden en dan is het af. Jaimy is veel bezig met Sam. Ruben zegt dat hij het in zijn planning moet zetten zodat er geen achterstand komt. Eind deze week is Korben wss klaar. Hij gaat miss Sam zijn project overnemen. \r\n\r\n10-05-2022: Korben heeft alles afgerond. Ze moeten alleen nog testen.\r\n\r\n17-05-2022: Korben heeft een nieuw project nodig. Ze hebben nog geen acceptatie test gedaan. \r\n\r\n14-06-2022: bezig met documentatie, eindoplevering moet ingepland worden\r\n\r\n21-06-2022 Documentatie aanpassen, bezig met feedback te verwerken. \r\n\r\n28-06-2022: Is meer bezig geweest met keuzendelen systeem. Niet veel vooruitgang verder. Nog een klein onderdeel afmaken. Er is een kleine mogelijkheid dat Korben stopt. Dit is echter nog niet zeker. Hij neemt contact op met Korben  zodat ze wel nog het project kunnen afronden.\r\n\r\n08-07-2022: mail gestuurd naar klant, nog geen antwoord. manifest is af dus moet alleen geÃ¯mplementeerd worden.\r\n\r\n05-10-2022: nog geen offerte verstuurd, vorige week woensdag is deze verstuurd. Er is nog geen telefonisch contact opgenomen. Dit gaat hij zo snel mogelijk oppakken.\r\n\r\n1-11-2022: hij heeft wat contact met de klant gemaakt, dit ivm. de komende meetings. \r\n\r\n08-11-2022: Moet nog een factuur gestuurd worden. Hiervoor word contact opgenomen met Norah.', 'Software', 'ES-2021-06', 'Dylan', '07/12/2022 11:50'),
(30, 'Branding CinnaMiddle', 'Teun Aardewerk', 'Evie Jongbloets', 'Normaal', 'Wouter Mahu', 'Teun Aardewerk', 'Teun Aardewerk', 'Teun', 'Teun Aardewerk', 'Afgerond', 'Branding voor gebak/voedings product\r\n2022-01-18: morgen of donderdag concept pitch\r\n2022-01-26: Concept pitch ging goed. Donderdag oefenpitch. Vrijdag ontwerppitch.\r\n2022-02-01: Ontwerp pitch is gedaan. Hij moet het logo nog perfectioneren.\r\n15-02-2022: Het ontwerp was niet goedgekeurd. Nu wel, dus kan er verder mee gegaan worden. Morgen oefenpitch, donderdag realisatie pitch.\r\n02-09-2022: slecht klant contact met Evie, wouter probeert hier iets aan te doen.\r\n\r\n15-03-2022: Klant contact is opgelost. Opleveiring is geweest, moeten een paar aanpassingen gebeuren. Morgen is het waarschijnlijk afgerond, hij zal dit laten weten. \r\nHij wilt even geen nieuw project, omdat hij aan documentatie wilt werken voor levels\r\n22-03-2022: Het is zo goed als afgerond. Hij moet het doorsturen in verschillende bestanden. Hopelijk vandaag anders morgen gebeurd dit. \r\n\r\n29-03-2022: Project is compleet afgerond. Hij moet Evie nu een berichtje sturen. Factuur moet nog geregeld worden.  Als het kan voor morgen de deur uit.\r\n', 'Media', 'EM-2022-06', 'Katja', '05/04/2022 12:51'),
(31, 'Keuzedelen website Scalda', 'Sam de Kock', 'Rebecca Boelens', 'Normaal', 'Cees-Jan Berman', 'Sam de Cock', 'Jaimy Zegers', 'Sam de Kock', '-', 'Factuur', 'Voor de zomervakantie basiswebsite - Daarna verdere functionaliteit + evt app met Vlissingen (projectleider was Arran Crowley) - 25-9-19 gesprek, klant kan desnoods site online zien.Realisatie - goed, Sam nog druk  met import func. 25-9-19 testen - erna gesprek. - Oplevering gehad, sprint gehaald volgende sprint weer door. \r\nAfgelopen sprint is gefactureerd, 8-10-2019 zijn de laatste sprints betaald.\r\n2019-11-27: KBS - Loopt iets achter met realisatie - documentatie is wel af. Realisatie is 3 ond - inlog, import kzd, meerdere opleidingen aan kzd koppelen.\r\nMeerdere kzd koppelen is wat lastiger - Arran gaf idee om tabel in te voegen - zit nu vooruitgang in. Tom hoopt dat dit vandaag af is.\r\n2019-12-18: KBS - Tom afwezig, 3 uur oppakken\r\n\r\n2020-1-8: KBS - Gaat vandaag nog een keer testen en dan donderdag oplevering.\r\n\r\n2020-1-14: KBS - Afgelopen week klantgesprek gevoerd, puntjes afgewerkt nu nog toevoegen keuzedeel. Arran Crowley heeft misschien iets dubbel aangepast waardoor code niet werkt, word vandaag nog gefixed. Aankomende donderdag oplevering klant -> Aankomende sprint user stories op een rijtje zetten. -> WIL GRAAG NOG IEMAND ERBIJ\r\n\r\n2020-3-10: project loopt redelijk op schema, project groep is een beetje uit balans omdat sam steeds ziek is \r\n\r\n2021-28-09: morgen oplevering geen problemen.\r\n\r\n2021-10-05: oplevering verzet\r\n\r\n2021-10-12: acceptatie test over 2 weken\r\n\r\n2021-10-19: Sam. Acceptatie word verzet naar 24 November\r\n\r\n2022-01-11: Hij gaat samen zitten met Melissa. Dan kan ze haar acceptatie test doen, stond al sinds 24 november ingepland. Hij moet de meeting in de agenda zetten vandaag. \r\n\r\n15-02-2022: sam planned nu een datum in voor het opleveren voordat hij de vergadering verlaat\r\n\r\n09-03-2022: sam gaat rebecca bellen om te vragen of ze vrij is voor de vergadering. en zal het daarna aan gerhard vragen\r\n\r\n15-03-2022: Volgende week is hij met de klant samen. \r\n\r\n05-04-2022: Moeten meeting inplannen voor acceptatie. Er ging iets mis me de life versie, dus moet die opnieuw. Hij moet met Gerhard zitten. Dit moet gepland worden voordat hij de meeting uit is. Ruben vraagt zich af hoe hij dit met kosten bijhoudt. Hij moet daar met Gerhard samen over zitten. \r\n\r\n12-04-2022: Voor oplevering morgen. Waarschijnlijk online. Nu is hij op hetzelfde punt. Hierna kan de acceptatie gedaan worden. Volgende keer wel een planning maken, of als het fout is.4\r\n\r\n19-04-2022: Jaimy gaat dit misschien overnemen.\r\n\r\n10-05-2022 oplevering staat voor maandag, klant is nog niet geÃ¯nformeerd. \r\n\r\n17-05-2022 Oplevering staat gepland voor dinsdag. Iedereen heeft akkoord gegeven dat ze kunnen. Klant heeft nog niet geantwoord. Mail functie werkt nog niet naar behoren daar zijn ze nu mee bezig.\r\n\r\n14-06-2022: Over twee weken oplevering, documentatie maken en applicatie afmaken. Bugs oplossen en laten testen door 5 studenten. \r\n\r\n21-06-2022: Hosting pakket verzorgd, nu nog bij de klant neerleggen. Nog geen reactie hierop.  Ze gaan komende donderdag testen met het product. Zsm. contact opnemen met de klant. \r\n\r\n28-06-2022: Oplevering net gehad, ging goed. Nog even de feedback verwerken. Volgende week staat een nieuwe oplevering gepland. Dit is de laatste oplevering.\r\n\r\n08-07-2022: factuur is gemaakt, deze moet nog nagekeken worden. dit factuur moet alle kosten van het hele project vergoeden. wij doen geen betalingen voor Scalda om ons terug te betalen aan het eind van het jaar voor hosting. dit moeten ze even bespreken.\r\n\r\n05-10-2022: Er is wonder boven wonder nog een puntje bij gekomen MAAR HIJ HEEFT HET EINDELIJK AFGEROND. Wacht nog wel de goedkeuring van de klant af. Hij moet zsm. telefonisch contact opnemen met Rebecca. Hij gaat daarna de factuur versturen.\r\n\r\n1-11-2022:  hij moet nog wachten op akkoord van Cees-Jan. Hij moet wel snel actie ondernemen zodat hij verder kan werken aan een volgend project. \r\n\r\n\r\n: Woensdag heeft Sam een gesprek om het project over te dragen. Vrijdag oplevering.\r\n', 'Software', 'ES-2019-23', 'Justin1', '07/12/2022 13:07'),
(32, 'Pleegouders website', 'Yoran de Blaey', 'Sophie Leenknecht', 'Normaal', 'Cees-Jan Berman', '+31 6 233 709 98', 'info@pleegoudersupport.nl', 'Yoran de Blaey', 'Rick van Tilburg', 'Bezig', 'Initiatie is gedaan door Rick v T: Coach Jesse. Wacht op notulen.\r\nAdres:\r\nRapenburg 101 Vogelwaarde\r\nProjectnaam:\r\nOmzetten website\r\nUitleg project\r\nHoi,\r\nWij zouden de website van pleegoudersupport graag willen updaten en via een ander besturingssysteem uitzetten. Ik ben namelijk vanuit andere organisaties gewend om te werken met wordpress en zou dat ook graag voor deze website hebben.\r\nIk heb eerder een aanvraag ingediend hiervoor, maar geen reactie ontvangen / een foutmelding ontvangen dus weet niet of hij toen is aangekomen.\r\nGroeten Sophie\r\n2021-10-14: klaar om te starten\r\n2021-12-07: Vanochtend de documentatie gekregen samen met een offerte, ook heeft hij de concepten binnen.\r\n2021-12-16: Sprint 1 gehaald, had dinsdag oplevering. nu nog implementeren en volgende sprint voorbereiden\r\n2022-01-11: Pleegouder website. Hij heeft paar aanpassingen aan TO gedaan. Verder is hij bezig met realiseren.\r\n2022-01-18: Aaron, is bezig met realiseren. Vrijdag is oplevering\r\n2022-01-25: Vorige week heeft hij opgeleverd. Hij is nu aan het implementeren.\r\n22-03-2022:  net klaar met documentatie. Vandaag of morgen gaat hij paar voorstellen doen en daarna gaat hij beginnen met realiseren.\r\n\r\n29-03-2022: Hij doet nu realisatie, bijna klaar. Begint met implementatie. Er komt zeker een volgende sprint \r\n\r\n04-05-2022: bezig met sprint offert. Morgen gaat hij met de klant zitten. Hij is bezig met documentatie en feedback gekregen. Hij loopt op schema.\r\n\r\n12-04-2022: Hij zit begin realisatie.  Nu is hij aan het implementeren. De planning loopt beetje uit, maar deze is aangepast. \r\n\r\n10-05-2022 Heeft net oplevering gehad, een functie deed het niet. Ondanks dat heeft hij akkoord gekregen van de klant. Hij moet nog opnieuw testen daarna gaat hij van de week aan de retro beginnen.\r\n\r\n17-05-2022 Hij loopt iets achter op schema. Hij heeft wat meer tijd nodig voor de implementatie. Hij wilt graag de documentatie voor van de week afhebben, dan loopt hij weer op schema. Hij heeft ook nog wat achterstallig werk doordat er verschillende taken en lessen tussen zijn gekomen. \r\n\r\n31-05-2022 Ruben is net klaar met zijn realisatie fase. Hij gaat van de week nog feedback verwerken zodat hij volgende week met de klant afspreken zodat alles kan worden afgerond voor door te gaan naar de volgende sprint\r\n\r\n07-06-2022 Ruben loopt iets achter omdat hij onderschat had hoeveel tijd hij ging missen ivm veel vrije dagen. Eindoplevering staat nog vast en denk datum wel te halen.\r\n\r\n14-06-2022: Meeting ging gister niet door ivm geen wifi. Nieuwe meeting nog niet ingepland, wachtend op antwoord van klant. Er is een error opgekomen, de reden is al achterhaald.\r\n\r\n21-06-2022: Vandaag oplevering gehad van de vorige sprint. Sprint goedgekeurd, volgende sprint zal een error oplossen zijn. Er moeten namelijk wat dingen worden aangepast. En een manier te bedenken om af te melden voor de nieuwsbrief. \r\n\r\n28-06-2022: Hij is bezig geweest met documentatie. Langzaam klanten contact. Weinig response. Vandaag contact gehad via de mail over bepaalde wensen en eisen. Hij gaat nu beginnen met realiseren.\r\n\r\n08-07-2022: oplevering staat al ingepland. Er word binnenkort opgeleverd en dat moet er nog besproken worden of er een extra sprint bij komt. \r\n\r\n21-09-2022: project moet opgepakt worden door iemand anders. er is nog niks betaald. er moet nog een spam filter over het contactformulier.\r\n\r\n08-11-2022: Heeft in de vakantie de documentatie gemaakt en deze opgestuurd. Vanaf maandag begint hij met realiseren \r\n\r\n7-12-2022: Hij wacht nog op een reactie van de klant wanneer dat ze naar locatie kan komen voor oplevering. Hij is nu bezig met documentatie voor volgende sprint.\r\n', 'Software', 'ES-2021-17', 'Dylan', '07/12/2022 11:52'),
(33, 'Langer thuis wonen (LTW)', 'Mathieu Heyndrickx', 'Nelleke Nelis', 'Normaal', 'Cees-Jan Berman', 'Mathieu Heyndrickx', 'Mathieu Heyndrickx', 'Mathieu', 'Mathieu Heyndrickx', 'Gestopt', 'X-over project met studenten van Zorg en Welzijn, electro, ICT beheer\r\nHoe kunnen ouderen langer thuis blijven wonen? \r\nDigitaliseren en uitvoeren van een Scan (vragenlijst).\r\n\r\n2021-09-28: doorstart document gemaakt en doorgestuurd, zijn nu in afwachting van reactie. heeft meer man op zijn project nodig.\r\n\r\n2021-10-05: Nogsteeds heeft hij mensen nodig. Klant heeft gereageerd en is akkoord. Nu heeft hij team nodig en dan samen planning maken. De klant weet hiervan.\r\n\r\n2021-10-12: Justin zit nu bij het project. Er is nog geen contact met de klant geweest. Ze zijn bezig met de planning.\r\n\r\n2021-10-19: Mathieu. Met Justin gekeken met Gerhard voor ondersteuning. Ze weten op het moment niet hoe verder dus bespreken ze dit met leraren. Ze gaan verder met documentatie en technisch ontwerp. Documentatie is deze week als het goed is af.\r\n\r\n2021-11-02: Robbie op project gekregen planning word aangepast omdat Robbie erbij is documentatie is af behalve planning\r\n\r\n2021-11-09: De taken verdeling is klaar. Codering is begonnen. Planning is klaar. Morgen neemt hij contact met Nelleke op en stuurt hij de planning.\r\n\r\n2021-11-16: Justin heeft de planning niet opgeslagen, dus hij is nu opnieuw begonnen. Zelf is Mathieu bezig geweest met het project. dit loopt allemaal verder soepel\r\n\r\n2021-11-30: Mathieu. Planning is aangepast voor de nieuwe sprint. Robbie is na deze sprint weg\r\n\r\n2022-01-11: Morgen gaat hij planning en plan van aanpak maken. Een paar user story\'s zijn af\r\n\r\n2022-01-25: Hij gaat vrijdag een deel opleveren. Hij heeft afgesproken om wekelijks contact te houden omdat het een redelijk groot project is. Dinsdag 1 feb is oplevering, samen met Gerhard.\r\n\r\n2022-02-01: klantgesprek ging goed. heeft tussenoplevering op 11 februari\r\n\r\n15-02-2022: zijn tijdelijk wat hosting aan het opzetten voor de klant haar eigen tussenoplevering aan het bestuursraad. ze proberen vervolgens verder te werken aan documentatie recht te trekken en \r\n\r\n22-02-2022: zijn verder gegaan aan documentatie en gaan de user story\'s afronden deze week.\r\n\r\n02-09-2022: er worden 2 user story\'s mee genomen naar de volgende sprint. Antony vervangt Ruben op het project. ze proberen alle documentatie eind week 1 af te hebben.\r\n\r\n15-03-2022: Plan van aanpak en sprint offerte is af. Hij is beZig met functioneel ontwerp. Maandag gesprek gehad en deze was tevreden en ze is op de hoogte. volgende afspraak is 4 april. De planning is af, staat in teams.\r\n\r\n22-03-2022: Documentatie is bijna recht getrokken. Vandaag is hij al gaan realiseren. Hij zit op schema. \r\n\r\n29-03-2022: Volgende week maandag is oplevering van sprint. Ze zijn bezig met laatste user storys. Antonie is bezig met sterre beoordeling. Documentatie is rechtgetrokken. Hosting is gevonden. Ze zijn bezig met implementatie plan\r\n\r\n05-04-2022:  Maandag met de klant gezeten. Hij is bezig met de documentaties. \r\n\r\n12-04-2022: Documentatie is doorgestuurd. Loopt terug op schema. Realisatie loopt goed.  Over 2 weken maandag is een afspraak gemaakt. User story\'s zijn zelfde en is 1 bijgekomen van de klant. Planning is bijgewerkt, moet hij nog doorsturen.\r\n\r\n19-04-2022: Vanochtend met de klant gesproken. Ze is niet tevreden, omdat het te traag gaat. Samen met Antonie gezeten en planning gemaakt. De klant heeft deze ook al. Na deze sprint moet het project af zijn. Hij loopt een week achter, maar kan hij in de vakantie rechttrekken. \r\n\r\n10-04-2022: hij heeft in de vakantie met de klant gesproken. Voor vrijdag staat nog iets ingepland met de klant. Hij heeft een fout maar heeft geen idee waar het aan kan liggen. \r\n\r\n10-05-2022: Hij heeft maandag ochtend oplevering gehad, hij heeft aan de klant laten zien wat af en niet af was. Hij gaat hier waarschijnlijk nog een sprint aanvast plakken, dit doet hij omdat hij de functionaliteiten veilig en naar behoren zijn. \r\n\r\n31-05-2022: Hij had gisteren normaal een klant gesprek, door slecht internet is dit niet door kunnen gaan. Ze gaan nu met de klant een nieuwe datum inprikken. Gerhard gaat hierbij zitten. Antonie valt weg van dit project, Mathieu kan dit in principe verder oppakken. Korben zou eventueel nog even bijspringen mocht het nodig zijn als mathieu in tijdsnood komt. \r\n\r\n07-06-2022: Antonie is gestopt met de opleiding. Oplevering moet verzet worden ivm Cyber Security event op 10 juni. Klant geeft aan: Het liefst volgende week dinsdag een meeting.\r\n\r\n14-06-2022: Meeting is ingepland met Nelleke en Gerhard voor oplevering van de vorige sprint. Is documentatie aan het rechttrekken. Userstory\'s zijn af op 1 na. \r\n\r\n28-06-2022: Vandaag bezig geweest met implementatie plan, zo goed als af. Nu nog een test inplannen. Dit loopt tot nu toe goed. Ondertussen houd hij zich bezig met de styling en wat aan de beveiliging imputs te werken. Heeft volgende week maandag oplevering staan.\r\n\r\n08-07-2022: woensdag oplevering gehad, er is afgesproken dat volgende woensdag alles af gaat zijn. dit moet voor de 19e geÃ¯mplementeerd worden. \r\n\r\n21-09-2022: Project staat nog te ver af van voltooiing, Mathieu redt dit niet op tijd voor zijn examen omdat Kevin er alleen op donderdag is, en gaat van dit project af. Project op hold tot dit opgepakt kan worden (misschien kan Kevin het afronden) of gestopt.', 'Software', 'EC-2021-69', 'Ruben', '04/11/2022 11:05'),
(34, 'Corrosie', 'Sam de Kock', '-', 'Normaal', 'Gerhard Hoogendoorn', 'Sam de Kock', 'Sam de Kock', 'Sam', '-', 'Afgerond', 'Project info: klant wil dat er bijgehouden wordt wat de temperatuur is van de buis, \r\nzodat ze hieruit kunnen kijken wat dit heeft gedaan met de buis.\r\n\r\n2021-10-19: Bezig met documentatie voor project en onderzoek.\r\n\r\n2021-11-02: arduino bestelt ook geleverd bij bedrijf, volgende week gaat hij er mee beginnen, in de tussen tijd onderzoek doen aan hoe hij het gaat maken\r\n\r\n2022-01-11: hij gaat woensdag samen zitten, maar weet niet zeker of dat doorgaat. Hij gaat samen met andere werken. Als het niet doorgaat moet hij het donderdag doen.\r\n\r\n2022-01-25: hopelijk volgende week afgerond\r\n\r\n15-02-2022: sam moet alleen nog wat documentatie bekijken\r\n\r\n15-03-2022: Sam moet nogsteeds documentatie bekijken. Gerhard kon de hele tijd niet, daarom duurt het zo lang. Sam moet met Gerhard bespreken dat het niet kan dat hij accepteert en niet op komt dagen voor de besprekingen. \r\n\r\n12-04-2022: Documenten was vrijdag gepland. Moet opnieuw ingepland worden.\r\n\r\n10-05-2022 hij heeft niet echt een update. \r\n\r\n17-05-2022 Gerhard had geen tijd, dus is nog niet verder gegaan. ', 'Software', 'IS-2021-12', 'Ruben', '13/06/2022 10:41'),
(35, 'Bos-Grens', '-', 'Lars Bosgrens', 'Normaal', '-', '-', '-', '-', '-', 'Gestopt', '(Was examen project) Afgelopen Dinsdag heeft Lars van Bos-Grens de samenwerking met IVS opgezegd en is zijn eigen weg gegaan rondom het project. Voor mijn examen is nu het project CityRun IVS in het leven gebracht dit zal het zelfde principe zijn als het Bos-Grens project maar dan voor het evenement CityRun wat meestal in de introductieweek van IVS gedaan wordt\r\n\r\n2021-11-30: Jeffrey. Plan van aanpak ligt bij de klant. Hij is al bezig met functioneel ontwerp.\r\n2021-12-07: de klant laat volgende week dinsdag weten of hij door gaat met het project. overige situaties worden besproken met gerhard i.v.m. examen\r\n2021-12-16: Vanmiddag het 6de uur heb ik hiervoor een startgesprek met Katja & Lana hun zullen als PR team van IVS mijn klantrol invullen voor de komende examen-sprint.\r\n\r\n2022-01-11: Technisch ontwerp is al opgestuurd. Dan kan hij realiseren.\r\n\r\n2022-01-18: Jeffrey. Afronden van zijn realisatie.\r\n\r\n2022-01-25: omdat de offline modus niet lukt. Hij gaat klant informeren als het voor morgen niet lukt. Dan heeft hij een goedgekeurde acceptatie voor z\'n examen. (Hij loopt 2 dagen uit)', 'Software', 'ES-202?-??', 'Tristan', '22/09/2022 13:42'),
(36, 'Website Zeeuwse Kringloop', 'Robbie Minderhoud', 'Melissa Poppe', 'Normaal', 'Jesse Vermeer', 'Robbie Minderhoud', 'Robbie Minderhoud', 'Robbie', 'Tom Kuijper', 'Afgerond', 'Er is een website mat plugin opgezet door Tom \r\nEr is een ontwerp voor de website gemaakt door Jared\r\nHet ontwerp moet nu over we website gehangen worden\r\n21 juni: GH contact met klant  over status nu Joost bij IVS weg is.\r\n2021-09-28: Robbie gaat dit oppakken\r\n2021-10-12: Robbie. Hij is net begonnen. Hij is de wordpress site op zï¿½n pc aan het zetten en kijken wat het probleem is. Hij heeft al gesprek met de coach gehad. Nog geen klant contact gehad\r\n2021-10-19: Robbie. De eerste issue is opgelost. 2x in de week klant contact. Er zijn twee problemen, een is simpel en bijna af. Tweede is moeilijker. Hij heeft geen documentatie gemaakt, omdat de klant snel dit probleem wilde oplossen.\r\n2021-11-09: Robbie, zeeuwse kringloop. De eerste ticket is vorige week af. Deze week gaat hij de tweede ticket afronden.\r\n2021-11-16: loopt allemaal soepel, heeft vorige week review gehad met de klant. Heeft een eindgesprek aangevraagd bij de klant zodat hij het project kan afronden. Hij wil de puntjes op de i zetten, hij wil dit liefst van de week dat gesprek hebben met de klant. Dit licht er aan wanneer de klant kan.', 'Software', 'ES-2020-11', 'Ruben', '-'),
(37, 'ZAOS Bekostigingssysteem', 'Casper van Mook', 'Willem Poppe', 'Normaal', 'Sander Bruggeman', '-', '-', 'Casper van Mook', 'Aaron Wakefield', 'Gestopt', 'Wij zijn een groot samenwerkingsverband (inmiddels bekend bij Innovision) tussen alle VO en MBO scholen in Zeeland en wij leiden leraren op. De ZAOS ontvangt geld voor de begeleiding van leraren in opleiding (onze studenten). Dit geld wordt verdeeld over de opleidingslocaties. We hebben daarvoor een complexe Excelsheet voor gebouwd die bij juiste opgave door de schoolopleiders uitrekent hoeveel geld er per type student naar de opleidingslocaties overgemaakt dient te worden. Omdat we veel moeten knippen en plakken in deze sheet gaat er nogal eens wat mis met formules. Graag zouden wij een applicatie gebouwd hebben die de invoer vergemakkelijkt voor de schoolopleiders aan de voorkant en voor onze administratie aan de achterkant. En misschien kan de applicatie wel gekoppeld worden aan de stageapplicatie die jullie studenten voor ons gebouwd hebben die binnenkort wordt opgeleverd! Omdat ik hele goede ervaringen heb met jullie bedrijf zou ik deze leer/werkopdracht weer graag door Innovision willen laten uitvoeren.\r\n\r\nAaron Wakefield in Examenproject gedeelte uitgevoerd.\r\n2021-06-21 Na examen Aaron geen capaciteit om op te pakken. Wacht op doorstart.\r\n2021-09-28: is aan het realizeren loopt klein beetje achter\r\n2021-10-05: Aaron. Project gaat goed. Donderdag oplevering. Realisatie is klaar.\r\n2021-10-12: Aaron. Gister gebeld. Nu is hij bezig met documentatie voor volgende sprint. Hij wilt miss een project erbij voor volgende sprint, omdat hij examen heeft dan. Dat is met Vincent besproken en zijn idee.\r\n2021-10-19: Aaron. Documentatie is bezig. Feedback verwerken morgen en samen met Sander zitten morgen. Hij wilt iemand om hem te vervangen op het project omdat zï¿½n volgende sprint examen is. \r\nHet is een wordpress program dus heeft hij iemand nodig die daar goed in is om het project te vervangen.\r\n2021-11-02: gaat volgende sprint beginnen met examen, bezig met realisatie en documentatie is doorgestuurd\r\n2021-11-09: Zoas, Aaron. Realisatie is af. Vandaag is getest, dus hij loop op schema\r\n2021-11-16: bezig met inplementere, en dan verder klaar. Hij geeft aan dat hij op schema loopt\r\n2022-01-18: gaat de goed richting op, gaat niet alles afhebben voor de deadline (28 januari). maar hij kan op tijd een testomgeving opzetten\r\n2022-02-01: is al goed onderweg met documentatie\r\n15-02-2022: Laatste aanpassingen aan documentatie worden gemaakt. \r\n22-02-2022: robbie is ziek, casper heeft moeite met de database op zijn computer. Mathieu en Casper gaan hiervoor nog samen zitten.\r\n02-09-2022: Casper zit vast omdat Robbie niet meer naar school komt. ook heeft hij een database error waar hij niet van af komt. Gerhard en Kylie zijn aan het regelen dat Robbie weer naar school komt.\r\n15-03-2022: Database probleem is opgelost. Robbie pakt niks op deze sprint zegt hij. Morgen begint hij aan realiseren. Casper moet het nr van de klant nog krijgen. Casper moet misschien RObbie bellen zodat hij sneller reageert. \r\n22-03-2022: Robbie is nog steeds thuis en doet niks aan het project. Casper heeft mails gestuurd. De klant heeft mails naar Gerhard gestuurd, omdat de klant niks van Casper zelf kreeg. Uit vorige documentatie weet hij welke user story\'s hij moet doen. Casper moet inplannen alsof hij het alleen verder doet, omdat Robbie waarschijnlijk niet snel terug komt. Damien is er en die kan misschien Casper helpen met het project, maar dit moet besproken worden met Gerhard. \r\n29-03-2022: Hij heeft klant gesprek gehad. Klant was gefrustreerd,  door klant contact, dit is opgepakt. Hij gaat volgende sprint beginnen en nu is hij bezig met user story\'s.\r\n\r\n12-04-2022: Vanmiddag project bespreking met Gerhard. Ze gaan oplevering met Willem inplannen. Ontwerpen moeten aangepast worden. Documentatie moet naar klant gestuurd worden daarna realiseren. \r\n\r\n19-04-2022: Vorige week een gesprek. Hij kreeg vorige week punten die hij deze sprint moet doen. Hij is dus nu al beetje bezig met documentatie. Hij heeft user story\'s in lijstje gezet en gaat kijken wat haalbaar is. Hij gaat misschien ook in de vakantie doorwerken. Eind oplevering is al gepland.\r\n\r\n17-05-2022 leerofferte en sprint offerte afgemaakt. Nog wat feedback op gekregen. Klant was tevreden\r\n\r\n31-05-2022 Hij is nu bezig met een probleem op te lossen. Hij heeft contact opgenomen met de klant, hierin heeft besproken voor de oplevering van deze sprint. De klant vond dit niet persÃ© nodig. Hij gaat dit verder nog afspreken met Gerhard ( om dit misschien online op te leveren.) \r\n\r\n07-06-2022: Loopt een beetje stroef. Wacht reactie af van Willem. Speelt liever Angry Birds.\r\n\r\n14-06-2022: Oplevering zou vandaag plaatsvinden maar werd kwartier van te voren afgezegd door Willem ivm belangrijk gesprek. Nieuwe oplevering wordt gepland en Casper gaat ondertussen al verder en zet op de mail wat hij gaat doen zodat Willem er vanaf weet. \r\n\r\n21-06-2022: begonnen met realiseren, documentatie moet nog worden nagekeken door gerhard. oplevering moet nog worden ingepland. \r\n\r\n28-06-2022: Een van de userstories afgerond voor deze sprint. Is nu begonnen aan de tweede. Als hij morgen nog geen reactie van de klant heeft gaat hij telefonisch contact opzoeken.\r\n\r\n08-07-2022: volgende week woensdag oplevering. is nu bijna klaar met de user story\'s\r\n\r\n05-10-2022: Hij is realiseren aan het afronden, hij gaat morgen met Ruben samenzitten om samen over het project te praten. Om de eventuele verder vooruitgang samen te bespreken en vanaf dit punt verder naar een oplevering te werken. \r\n\r\n2022-10-11: Is in afwachting of het project nog door kan gaan of we het stoppen. Deze sprint geen oplevering gedaan, deze sprint proberen toch iets op te leveren.\r\n\r\n18-10-2022: Cees-jan heeft besloten het project defenitief te stoppen. Ze gaan nu samen beiden even kijken hoe dat ze dit verder op gaan pakken. Deze sprint maakt hij wel af voor dit project. hierbij zit hij in week twee voor deze sprint.\r\n\r\n1-11-2022: hij is bezig met het project stop te zetten. De klant is met een paar vereisten gekomen die niet volledig duidelijk zijn. Dit moet nog worden doorgenomen zodat ze deze dingen in orde kunnen krijgen. Dat de project overdracht kan plaats vinden en zo ja hoe?\r\n\r\n07-11-2022: Casper zit niet meer op het project. Cees-Jan en RenÃ© bespreken vervolg met de klant.\r\n\r\n29-11-2022 : Casper heeft een mail naar willem gestuurd. Hier heeft hij met Kevin naar gekeken. ', 'Software', 'ES-2020-13', 'Dylan', '29/11/2022 11:28'),
(38, 'IVS Website', 'Norah Blaauw', 'Tristan Verschueren', 'Normaal', 'Sander Bruggeman', 'Norah Blaauw', 'Norah Blaauw', 'Norah', 'Hamish Caldow', 'Afgerond', 'Linking staat nog op localhost, enkele afbeeldingen dienen nog toegevoegd te worden. \r\nDe contact pagina is een drama. Hier zijn 2 mensen nodig, \r\nï¿½ï¿½n werkt aan de linking en de ander werkt aan het contact formulier in de contact pagina. \r\nVerder is het prettig als de website dynamisch werkt. Nu is alles nog statisch \r\n(Iemand moet content op dit moment in de code veranderen).\r\n2019-11-01: GH - Joost Kools op stage\r\n2019-11-20: KBS - DOC af, nog niet goedgekeurd. - 404 nog niet aan gewerkt - Jasmijn ziek. Sprint: Website resp maken & 404 pagina maken.\r\n2019-11-27: KBS - Project gaat goed, vrijdag is oplevering - neemt aan dat hij deze sprint gaat halen\r\n2019-12-18: KBS - Formulier moet dynamisch was even een issue. Kan nog steeds niks online zetten. - Wanneer alles lokaal in orde is kan dit online.\r\n2020-1-8: KBS -Menu issue tablet versie geeft niet goed weer, gaat volgende week opleveren.\r\n2020-1-14: KBS - 404 pagina search bar moet nog gedaan worden, menu is gefixed.\r\n2021-09-10: Nora. Ze moet nog met katja over paar documenten bespreken. Ze loopt niet echt ergens tegenaan. Ze loopt een klein beetje achter, maar ze hoopt dit in te halen.\r\n2021-10-12: Nora heeft gesprek gehad met Kylie, Katja en Gerhard, apart. Ze krijgt het deze sprint niet af, maar er is al een plan om dit voor volgende sprint op te pakken\r\n2021-10-19: Norah. Gister gesprek gehad. Ze heeft een plan om op te pakken en gaat dan door.\r\n2021-11-02: planning beetje aangepast, begint 03/11/2021 met wordpress heeft een kleine vertraging en gaat dat vanmiddag thuis inhalen.\r\n2021-11-09: Norah, IVS website. Wordpress is geï¿½nstalleerd. Ze loopt beetje achter, maar ze kan dit wel inhalen. Alleen sander moet nog ondertekenen, maar hij is wel accoord\r\n2021-12-07: norrah is afwezig geweest door persoonlijke zaken, ze pakt de dingen van vorige sprint op\r\n2022-01-11: De offerte moet nog goedgekeurd worden door Sander. Ze is bezig met trealisatie.\r\n2022-01-19: Vorige week maandag sprint offerte gestuurd, maar ze heeft nog geen antwoord. Realiseren gaat wel goed. \r\n2022-01-25: ze loopt vaak uit op planning, volgende planning gaat ze laten controleren door een coach. en ze zal vragen om projectcoach te kunnen wisselen\r\n2022-02-01: bijna klaar met plan van aanpak. sander is nog steets projectcoach maar norah gaat dit nu anders aanpakken. en de planning zal gecontroleert worden.\r\n15-02-2022: feedback van de coach verwerkt opnieuw ingestuurd. ze wacht op reactie. ze ligt op schema met realizeren.\r\n15-03-2022: Vanochtend heeft ze met Gerhard gepraat. Ze meot alleen de sprint offerte en leerofferte maken. Ze moet vooral door met de site van Gerhard. De planning moet ze even aanpassen voor deze sprint en daarna moet ze deze in teams zetten. \r\n22-03-2022: Ze heeft documentatie over geslagen. Ze is bezig met user story\'s, deze heeft ze gestuurd naar Sander. Ze is verder bezig met realiseren. Ze loopt nergens tegen aan. Ze moet nog een paar pagina\'s toevoegen. Ze is vooral aant focussen op pagina\'s waar ze aan kan werken. complexere dingen pakt ze later op. Planning heeft ze bijgewerkt en op teams gezet. \r\n29-03-2022: Ze gaat het deze sprint opleveren. Ze heeft nog geen implementatie plan, maar moet deze week wel volgens Ruben. Morgen moet ze nog realiseren. Tristan gaat haar helpen met implementeren, want het is de eerst keer dat ze dit doet. Vrijdag is de planning dat de website online staat. \r\n\r\n27-06-2022: Binnenkort wordt er gekeken naar de inhoud van de website. Dit gaat in overleg met het IVS Management. Tijdelijk \'On Hold\' omdat er misschien gekeken gaat worden naar een nieuwe huisstijl voor IVS.\r\n\r\n22-09-2022: Project afgerond want nieuwe website staat live.', 'Software', 'IS-2018-39', 'Tristan', '22/09/2022 13:20'),
(39, 'Badge systeem', 'Ibraim Amet, Korben de Vos ', 'Vincent Brunings', 'Normaal', 'Sander Bruggeman', '-', '-', 'Ibraim Amet, Korben de Vos', 'JoÃ«l Schout', 'Bezig', '2021-09-28: technisch en functioneel zijn nog niet afgrond en zijn aan het realisatie.\r\n\r\n2021-10-05: Joel heeft aanpassingen gedaan. Casper kan weer verder gaan en moet css aanpassen. Als het goed is donderdag oplevering\r\n\r\n2021-10-12: JoÃ«l. Opgeleverd. Alleen nog implementeren.\r\n\r\n2021-10-19: Casper heeft plan van aanpak, sprint offerte. Leerofferte is gemaakt deze gaan ze laten goedkeuren. Deze week technische ontwerpen en hopelijk volgende week realiseren.\r\n\r\n2021-11-09: Hij doet nog kleine aanpassingen aan functioneel en technisch. Is vandaag of morgen wel af zegt Joï¿½l.\r\n\r\n2021-11-16: vrijdag acceptatietest gedaan, een verbetervoorstel naar vincent verstuurd. hij gaat nu aan het dashboard en profiel pagina te bewerken en de wijzigingen door te zetten. Dan nog een keer voorleggen bij Vincent voor akkoord.\r\n\r\n2021-11-30: Joel. Vandaag offerte opgestuurd. Deze week documentatie afronden. Vrijdag beginnen met testen. Bedoeling volgende week opleveren, donderdag uiterlijk.\r\n\r\n2021-12-07: realisatie is alles af. een paar aanpassingen aan documentatie geweest dat hebben ze in deze week van de sprint meegenomen, omdat de sprint een week korter is i.v.m. kerst.\r\n\r\n2022-01-11: badge systeem. Het plan van aanpak is goedgekeurd, functioneel ontwerp ook goedgekeurd. Technisch ontwerp is bezig, is waarschijnlijk morgen af. Hij wilt eind deze week realisatie af hebben. \r\n\r\n2022-01-18: Ze zijn aan het realiseren. Vrijdag oplevering\r\n\r\n2022-01-25: Ze hebben vanmiddag acceptatie verstuurd. Eventuele aanpassingen en daarna implementatie. Alle user storys zijn gerealiseerd.\r\n\r\n2022-02-01: hij gaat implementatie inplannen met Vincent, Gerhard gaat hierbij zitten als vervanger van sander omdat hij ziek is\r\n\r\n15-02-2022: Hij is aan het realiseren. Morgen samen met Sander documentatie nakijken. Donderdag oplevering.\r\n\r\n22-02-2022: alles is af, maar voor implementatie moet er nog wat omgebouwd worden aan de plugin om het te koppen aan het meeloopportaal. hiervoor gaat JoÃ«l met sander zitten.\r\n\r\n02-09-2022: implementatie gaat nog 1 sprint verder. maakt nieuwe planning en probeert het deze sprint af te ronden.\r\n\r\n15-03-2022: Komende dinsdag oplevering. Dan gaat hij implementeren. Deze week zet hij plug in op een portaal. Testen moet nog gebeuren. Deze week gebeurd dit allemaal, dan is hij eerder klaar.\r\n\r\n22-03-2022: Vandaag oplevering met Vincent. Acceptatie test heeft hij niet kunnen doen. Hij heeft afgesproken de test te sturen, dan gaat hij die maken. Dan gaat JoÃ«l implementatie plan maken en implementeren. \r\n\r\n29-03-2022: Hij is bezig met test omgeving online te zetten. Dit lukt niet echt. (met hulp van Sam) Het werkt wel maar ze kunnen niet in de wp admin. Hij wilt vandaag van de klant goedkeuring. Hij denkt dat het beste is om nu op zijn test omgeving te doen, omdat hij geen andere opties heeft. Anders loopt hij achter. Hij wilt deze sprint klaar zijn en Ruben heeft al een volgend project. Hij krijgt hele tijd een error, Michael gaat even mee kijken hiervoor.  \r\n\r\n07-09-2022: een mediavormgever moet badges maken.\r\n\r\n12-09-2022: Ibraim Amet pakt het project op.\r\n\r\n2022-10-11: Gister offerte ondertekend. Onderzoek voor concepten, kleurgebruik, etc.\r\n\r\n18-10-2022: net een initiatie gesprek ingepland. Hij gaat kijken of dat Cees-jan hierbij kan aansluiten. donderdag staat een gesprek ingepland, hierbij kan nu nog geen coach aansluiten. Hier moet hij wel voor waken dat dit niet vaker gebeurd. \r\n\r\n1-11-2022: hij heeft zijn initatie gesprek gehouden, dit heeft hij ook doorgestuurd naar zijn coach. Hij heeft zijn planning rond, nu moet hij goed gaan plannen dat hij zo goed mogelijk de sprints gelijk kan krijgen aan zijn project. \r\n\r\n08-11-2022\r\nKan beloofde functionaliteiten niet opleveren. Gaat zijn best doen om het zo ver mogelijk af te ronden. Donderdag staat de oplevering gepland. Gaat zich nu vooral focussen op de documentatie. \r\nKan eigenlijk geen fatsoenlijk product opleveren. Zegt dat de communicatie zo langzaam is dat hij daardoor achterloopt. \r\n\r\n29-11-2022 : moet nog worden geÃ¯mplementeerd worden. zijn project wordt nu stopgezet, als in de afronding van dit project. Sam moet nog bepaalde informatie naar Korben doorsturen. \r\n\r\n7-12-2022: Sam zou nog kijken naar het niet te implementeren. Hij heeft daar nog niks van terug gehoord. Hij wou niet updaten? Tristan benadert Sam hierover. ', 'Software', 'IS-2021-05', 'Dylan', '07/12/2022 11:16'),
(40, 'Migchiel van Diggelen', 'Menno de Pooter', 'Migchiel van Diggelen', 'Normaal', 'Vincent Brunings', 'Menno de Pooter', 'Menno de Pooter', 'Menno', 'Menno de Pooter', 'Gestopt', '2022-01-18: Ik ga een logo en een online platform maken voor de klant.\r\n\r\n2022-06-13: project is on hold gezet wegens slecht klant contact. hij is verdwenen', 'Media', 'EM-2022-03', 'Ruben', '04/11/2022 11:06'),
(41, 'Green Office', 'Nick Mulder', 'Caroline Passenier', 'Normaal', 'Vincent Brunings', 'Nick Mulder', 'Nick Mulder', 'Nick', 'Nick Mulder', 'Afgerond', '2022-01-18: Ik ben bezig met twee video\'s voor het Green Office van Scalda\r\n2022-25-01: Hij zit in de ontwerp fase. Morgen is ontwerp pitch\r\n2022-02-01: aankomende maandag gaat hij realisatie pitch houden\r\n2022-06-20: factuur is betaald, project is afgerond', 'Media', 'EM-2022-02', 'Ruben', '20/06/2022 10:47'),
(43, 'CO3 Campus', 'Jared Wolffensperger', 'Alexander Lie Kwie', 'Normaal', 'Vincent Brunings', 'Jared Wolffensperger', 'Jared Wolffensperger', 'Jared', 'Jared Wolffensperger', 'Afgerond', '2022-01-18: een huisstijlhandboek en visitekaartje maken', 'Media', 'EM-2022-04', 'Ruben', '07/04/2022 11:02'),
(44, 'Op Orde', 'Mats Segers', 'Esther Nillessen', 'Normaal', 'Wouter Mahu', '-', '-', 'Mats Segers ', 'Mats zegers', 'Bezig', 'Beste studenten,\r\nIk ben samen met een vriendin bezig met het opstarten van een bedrijf. Tenminste, we doen een poging en zullen zien wat er uiteindelijk van komt... Allemaal best spannend.\r\nWe (ik en Ilona) willen gaan starten als opruimcoach. We hebben al een naam en Logo (+ huisstijl handboek).\r\nDit laatste heeft een student van MV in Vlissingen voor ons gemaakt\r\nWe willen nu de volgende stap zetten en een website en Instagram pagina gaan maken maar hebben geen idee hoe en we begrijpen ook niet goed hoe we het huisstijl handboek moeten gebruiken.\r\nï¿½Hoe gaan we onszelf in de markt zettenï¿½ is dus eigenlijk de vraag waar we wel wat hulp bij kunnen gebruiken.\r\nIs dat iets voor jullie? Kunnen jullie ons helpen bij het opstarten en inrichten/mooi maken van een website en sociale media??\r\nGroetjes, Esther\r\n\r\n@Ruben, is dit een MV of Combinatie project? ~Tristan', 'Media', 'EM-2022-01', 'Amber', '04/11/2022 14:00');
INSERT INTO `project` (`id`, `projectnaam`, `projectleider`, `klant`, `prio`, `projectcoach`, `telefoonnummer`, `emailklant`, `projectleden`, `initiatieleider`, `project_status`, `opmerkingen`, `opleiding`, `administratienummer`, `bewerkt_door`, `bewerkt_datum`) VALUES
(45, 'Festival hart voor design', 'Jessica Asaad', 'Anne Kluijfhout', 'Normaal', 'Gerhard Hoogendoorn', 'Jessica Asaad', 'Kylian de Putter', 'Nathan, Jessica, Kylian', 'Nathan Stoffels', 'Gestopt', 'Website voor bedrijf. Komt via Jeroen van de Merwe uit Vlissingen binnen.\r\n\r\nHi Jeroen,\r\n \r\nZoals je weet organiseer ik jaarlijks een event. Nu heb ik hier alleen een salespage voor, maar inmiddels is er de behoefte aan een aparte website.\r\n \r\nIk zou t heel leuk vinden om dit als opdracht aan een aantal studenten van MediaVormgeven te geven.\r\nDe huidige salespage: buro89.nl/event\r\nOm een idee te krijgen van t event: buro89.nl/hart-voor-design-2021\r\n \r\nIk hoor graag of dit kan. \r\nEventueel kunnen de studenten ook direct contact met mij opnemen:\r\nanne@buro89.nl of bellen / whats-app: 0642942828\r\n \r\nGrts Anne Kluijfhout\r\n2021-09-28: gesprek gehad, begin info is binnen\r\n2021-10-05: Nathan. Offerte is gemaakt, feedback verwerkt en ze wachten op akkoord. Daarna gaan ze deze doorsturen. Jessica en Kylian hun leeroffertes zijn onderteken. Nu is het gewoon wachten op start.\r\n2021-10-12: Nathan. Bezig met tweede concept. Jessica en kylian voorbereiden voor 2de sprint. Ze moeten nog een officieel akkoord offerte.\r\n2021-10-19: Morgen ontwerp pitch. Leerofferte is nog niet gestuurd, maar word vandaag geregeld\r\n2021-11-02: 1/11/2021 gesprek met de klant gehad en verliep goed, jessica en kyllian zijn aan het realiseren, lopen op schema\r\n2021-11-09: Documentatie Jessica is hier druk mee bezig. Kylian gaat een plugin ombouwen. Nathan is ontwerpen aan het maken. Jessica denkt morgen middag klaar te zijn.\r\n2021-11-16: jessica is zo goed als klaar met de documentatie, kyllian is ook ver klaar met wordpress. hij moet alleen de lijst met de plug ins nog afronden. Nathan heeft in de tussentijd nog met de klant gesproken voor alles te bespreken van de ontwerpen. Zij gaf akkoord voor de ontwerpen. Volgende vergadering zitten waarschijnlijk Jessica en Kyllian in de vergadering voor het projcet\r\n2021-11-23: Wij zijn klaar met sprint 1, maar nu dat ons hele project groep naar huis was gestuurd vanwege corona konden wij gisteren niet onze oplevering houden, Deze wordt verzet naar A.s. maandag. Als de oplevering is geweest en goedgekeurd van de klant stop ik als project lid/leider en zal Jessica de nieuwe project leider worden.\r\n2021-11-30: Ik (nathan) blijft 1 sprint langer op het project. Jessica en kyllian zijn bezig met de line-up plugin, deze is wel bijna af. \r\nWij gaan nog samen zitten om een planning te maken hoe wij verder gaan aangezien ik nog langer op het project blijf.\r\n2021-12-07: Donderdag heeft hij een tussenmoment met de klant om alle ontwerpen te bespreken. Hierna gaat nathan realiseren. Hij geeft aan dat er geen problemen gaan zijn voor de realisatie alleen dat dit wat langer kan duren\r\n2021-12-16: van de week nog samen gezeten met de klant voor de ontwerpen, deze ben ik aan het uitwerken en volgende voor de oplevering moet ik nog contact opleggen omdat de klant volgende week niet meer kan.\r\n2022-01-18: er zijn wat onderliggende problem in de groep die uitgepraat moeten worden. binnenkort een meeting inplanning met Ruben en Michiï¿½l\r\n2022-01-25: team loop nog steets niet helemaal lekker. ruben zal een keer samen met jessica en kyliaan zitten.\r\n2022-02-01: team heeft met gerhard gezeten. nathan zal deze week zijn design opleveren, en dan alleen de site nog\r\n15-02-2022: Vorige week oplevering, feedback is al verwerkt hiervan en opgestuurd. Verder heeft hij akkoord en is hij klaar. Jessica en Kylian zijn bezig met een thema opbouwen. Volgende week dinsdag is een oplevering. Ze wijken af van het schema, het word een sprint langer door getrokken, want dinsdag is niet haalbaar.\r\n22-02-2022: Nathan zijn feedback is goedgekeurd en zal volgende week vervangen worden door Jessica in de vergadering\r\n02-09-2022: Vorige sprint heeft jessica niet kunnen opleveren dus hebben het verzet naar volgende week dinsdag. Kyllian heeft problemen met zijn laptop. Mocht alles goed zijn is hij er morgen anders pas donderdag. Kyllian heeft nog niet geÃ¯mplementeerd, dus dit zal hij nog een beetje onder de knie krijgen.\r\n22-03-2022: Klanten gesprek was vandaag. Project is niet af dus ze was beetje boos. HEt zag er niet uit als het ontwerp. Gerhard zijn idee was deze week opleveren. Donderdag komt ze en gaan ze het online zetten. Er moeten nog laatste puntjes op de i. \r\n\r\n29-03-2022: De klant is gestopt. Ze hebben vaak opleveringen verplaatst, de laatste keer was het internet uitgevallen, dus zou dat niet lukken. Toen belde de klant dat ze wilde stoppen. Ze hadden retrospective en dat was pittig. Als ze eerder hulp vroeg zouden ze het wel af hebben denkt ze. ', 'Media & Software', 'EX-2021-26', 'Tristan', '21/05/2022 13:19'),
(46, 'M Productions', 'Tycho Eekhout', '?', 'Normaal', '?', 'Tycho Eekhout', 'Tycho Eekhout', 'Tycho', 'Tycho Eekhout', 'Gestopt', '2021-10-12: Tycho. Hij is dit aan voorbereiden, volgende sprint gaat die van start. \r\n2021-10-19: Tycho is op schema hij is bezig met documentatie\r\n2021-11-02: planning iets moeten aanpassen ivm met realisatie gaat inplaats van 1 week 2 weken realiseren\r\n2021-11-09: Is op schema\r\n2021-11-30: Moet nogsteeds afgerond worden. Oplevering staat op vrijdag, gebeurd miss online, omdat Evie ziek is.\r\n2021-12-07: oplevering is nog niet geweest, de klant was ziek. vandaag wordt gevraagd voor deze pitch anders wordt er gemaild', 'Software', 'ES-2021-27', 'Ruben', '15/09/2022 12:58'),
(47, 'Mats Visser', 'Rick wagenaar', 'Mats visser', 'Normaal', 'Wouter Mahu', '-', '-', 'Rick Wagenaar', 'Rick Wagenaar', 'Factuur', 'Er moeten visitekaartjes, brochures, een raamsticker en foto\'s gemaakt worden.\r\n2021-11-09: Ik ben nu bezig aan mijn planning en offerte en die stuur ik z.s.m. naar de klant voor een akkoord.\r\n2022-02-01: Donderdag heeft hij concept pitch\r\n\r\nGestopt omdat de klant niet tevreden was met wat Timo leverde.\r\n\r\n29-03-2022: Dit is tweede week van het project. Hij heeft offerte gemaakt een naar de coach gestuurd, vandaag wilt hij dit naar de klant sturen. \r\n\r\n05-04-2022: Hij is nog steeds bezig met offerte. Wouter had geen tijd gisteren. Hij heeft niet aan een andere coach gevraagd. Hij heeft geen vast moment dat hij met de coach samen zit, wat wel slim zou zijn. Hij moet een deadline voor zich zelf zetten. Hij zegt vandaag.\r\n\r\n19-04-2022: Hij is aan het ontwerpen. De oefenpitch en gewone pitch is ingepland. \r\n\r\n10-4-2022: Oefen pitch donderdag en echte pitch vrijdag, is bijna klaar met de ontwerpfase. \r\n\r\n17-05-2022 gisteren pitch gehad met de klant, de klant gaf aan eerder visite kaartje te willen ivm een evenement hij wil dit voor de 31ste hebben zodat hij deze al heeft. \r\n\r\n21-06-2022: Gisteren alles verstuurd naar de klant, om een zeker akkoord te krijgen van de klant. Hierin heeft hij de aangepaste versie met feedback verwerkt verstuurd naar de klant. \r\n\r\n28-06-2022: Was nog kleine feedback. Hij gaat dat vandaag nog aanpassen en doorsturen. Hij moet alleen nog een factuur doorsturen naar de klant dit moet hij met financieel regelen.\r\n\r\n08-07-2022: project is klaar. factuur word nu opgestuurd', 'Media', 'EM-2021-30', 'Amber', '04/11/2022 13:48'),
(48, 'Geweuneweg', 'Lana de Rijk', '?', 'Normaal', 'Wouter Mahu', 'Lana de Rijk', 'Lana de Rijk', 'Lana', 'Lana de Rijk', 'Afgerond', '2021-11-16: is bezig met het maken van een video aan het maken voor het verpakkingloos te winkelen. Ze zit nu nog in de conceptfase.\r\n2021-12-07: film op locatie is twee weken verzet, een van de vereiste mensen was ziek 20/21 December is Lana weg voor te filmen. ze houd zich bezig met het oefenen met de camera. \r\n2021-12-16: maandag start filmen\r\n2022-01-11: Ze heeft een video zonder geluid. De audio word opnieuw opgestuurd. Video gaat over verpakking loze winkels. \r\n2022-01-18: audio is opgestuurd, was nog niet besluistert. al was het slechte audio had ze een plan B\r\n2022-01-25: Donderdag oefenpitch. Vrijdag realisatie pitch\r\n2022-02-01: maandag 2e oefenpitch gehouden. volgende week oplevering\r\n15-02-2022: De video is opgeleverd. De factuur gaat ze nog aan Mathieu vragen. Wouter of Vincent moet ze nog vragen, omdat iemand anders ging betalen.\r\n\r\n23 maart deadline voor betaling', 'Media', 'EM-2021-32', 'Ruben', '19/04/2022 10:50'),
(49, 'Sportmassage Veerse Poort', 'Roxanne van Hulle', '?', 'Normaal', 'Wouter Mahu', 'Roxanne van Hulle', 'Roxanne van Hulle', 'Roxanne', 'Roxanne van Hulle', 'Afgerond', '2021-12-16: Bijna klaar met realisatie fase. 2e sprint start wanneer dit af is.\r\n15-02-2022: zal komende week opgeleverd worden.\r\n\r\n18-10-2022:  aankomende vrijdag pitch voor kleine tussenoplevering.\r\nDe klant, Levi, doet er erg lang over om snel te reageren. Hierop heeft ze de klant wel al gewezen. ', 'Media', 'EM-2021-37', 'Dylan', '18/10/2022 10:58'),
(50, 'Logo Crossovers projecten', 'Katja Willemse', 'Melissa Dominicus', 'Normaal', 'Wouter Mahu', '-', '-', 'Katja Willemse', 'Katja Willemse', 'Factuur', 'Betreft: het ontwerpen van een logo voor de Crossovers \r\nAchtergrond:\r\nDe techniek en ICT- opleidingen van Scalda zijn in september 2019 gestart met ï¿½cross-overï¿½ projectonderwijs.\r\nStudenten vanuit verschillende opleidingen worden gemixt in een projectteam en gaan aan de slag met innovatieve vraagstukken uit het bedrijfsleven. De ambitie is om de projectteams te laten werken zoals dit het geval is in het bedrijfsleven: studenten gaan aan de slag met echte opdrachtgevers en leren projectmatig werken met agile en scrum.\r\nDit betekent dat projectmanagement en bijhorende tools een belangrijke rol gaan spelen in de opzet van het leren. Uiteindelijk zijn deze multidisciplinaire projecten bedoeld om een goede bijdrage te kunnen leveren aan een nieuw product, dienst of procesverbetering voor de klant (opdrachtgever).\r\nWie doet mee?\r\nStudenten uit opleiding werktuigbouw, elektro, ict beheer, applicatie ontwikkelaar Terneuzen, bouw-infra, motorvoertuigen en logistiek.\r\nLeren klantgericht te denken, samenwerken met andere disciplines, creatief zijn en doorzettingsvermogen ï¿½ pro actief handelen zijn de skills die je kunt trainen in deze projecten.\r\nBijzonder verder aan deze projecten is dat je hier leert out of the box te denken: idee is dat je met meerdere disciplines een oplossing kunt bedenken die je niet alleen met vakgenoten zou kunnen neerzetten. \r\nHet logo is bedoeld om PR te kunnen maken naar de buitenwereld:\r\nï¿½ Bedrijven en organisaties enthousiasmeren voor het verstrekken van een opdracht op dit terrein\r\nï¿½ Externen (ouders, andere ROC\'s, oud-studenten, organisaties) informeren over wat we doen binnen ons opleidingscluster.\r\nToepassingen waar het voor gebruikt wordt:\r\nï¿½ Linkedin bedrijvenpagina\r\nï¿½ Scalda landingspagina via de website\r\nï¿½ Communicatie naar studenten: uitnodigingen voor kick-offs, informatie over project(en)\r\nï¿½ Communicatie naar opdrachtgevers van de projecten: informatiemail, dankmail, uitleg over project\r\nï¿½ Formats die gebruikt worden tijdens de projecten (leerofferte; plan van aanpak;ï¿½.)\r\nï¿½ Voorlichting bij studenten (presentatie ï¿½ flyer ï¿½ filmpjes)\r\n\r\n2022-02-01: er is initiatie geweest, over 2 weken conceptptich\r\n15-02-2022: Deze week pitch concept fase. Klant contact gaat goed.\r\n22-02-2022: Concept pitch is geweest, ontwerppitch is na de vakantie staat vast.\r\n22-03-2022: De oefen ontwerp pitch is geweest. Volgende week maandag is ontwerp pitch voor de klant. \r\n29-03-2022: Heeft ontwerp pitch gehad en de klant was akkoord met het logo. Nu maakt Katja een paar aanpassingen en gaat het dan realiseren. Vrijdag is oefenpitch en dinsdag is haar pitch voor de klant. Deze is al ingepland.\r\n04-05-2022: Realisatie pitch vanochtend gehad. Nog een paar aanpassingen maken en dan stuur ik het logo met de factuur door. Hierna ga ik verder met ontwerpen van de huisstijl.\r\n\r\n12-04-2022: Logo is bijna af. Huisstijl word aangewerkt. Meeting is komende donderdag voor ontwerpen van de huisstijl. \r\n\r\n10-4-2022 Ze gaat deze week inplannen met de klant. Ze is bezig met haar huisstijl handboek. het project is richting de eind fase\r\n\r\n\r\n17-05-2022 vanochtend realisatie pitch, ze moest nog een klein ding aanpassen en dan donderdag heeft ze een oplevering.  ', 'Media', 'EM-2022-05', 'Amber', '04/11/2022 13:42'),
(51, 'Puur Zeeland', 'Jessica Asaad', 'Petra Jeras', 'Normaal', 'Vincent Brunings', 'Jessica Asaad', 'Jessica Asaad', 'Jessica Asaad', '-', 'Factuur', '2020-3-24: In de groep vragen wie dit zo snel mogelijk kan oppakken\r\nVoor de zomervakantie dat vanwege corona en bezettingsprobleem project nog niet opgepakt kon worden [VB]\r\n2020-9-10: Vrijdag 11 september is het initiatiegesprek\r\n2021-3-3: Klant betaald dmv workshop [vb]\r\n2021-09-28: heeft contact gehad, wilt een workshop geven rond marketing. word nog besproken\r\n2021-10-12: ze kan een workshop komen geven in januari, meer overleg is nog nodig om in te plannen\r\n2021-11-09: Ze kan in januari workshop geven, marketing workshop. Jessica moet dit inplannen en met Gerhard bespreken. Jessica gaat nu een mail sturen', 'Media & Software', 'EX-2020-11', 'Amber', '08/11/2022 11:25'),
(52, 'Instructievideo Brandweer', 'Nick Mulder', 'Aart van Oosten', 'Normaal', 'Vincent Brunings', 'Nick Mulder', 'Nick Mulder', 'Nick', 'Nick Mulder', 'Afgerond', '2021-11-16: heeft net de concept fase afgerond. hij gaat daarna aan de ontwerpfase beginnen, loopt verder op schema.\r\n2021-11-30: Nick. Heeft ontwerp pitch afgerond. Uitbesteding gevonden. Verder gaat alles goed. \r\n2021-12-07: klant reageert snel. loopt soepel, script is af dus Ik kan verder\r\n2022-01-18: factuur moet nog verzonden worden\r\n2022-01-25: factuur opgestuurt', 'Media', 'EM-2021-33', 'Ruben', '23/02/2022 03:18'),
(53, 'Blend & Solve', 'Jared Wolffensperger', 'Scalda', 'Normaal', 'Vincent Brunings', 'Jared Wolffensperger', 'Jared Wolffensperger', 'Jared', 'Jared Wolffensperger', 'Afgerond', '2021-12-07: huisstijl handboek en logo is gemaakt, conceptfase is af. is een intern project van scalda. volgende week maandag staat iets gepland met de klant. \r\n2021-12-16: Ik moet alleen nog alles opleveren en dan ben ik klaar. Volgende week dinsdag heb ik initiatie van mijn nieuwe project. Meer info hierover na mijn initiatie.', 'Media', 'EM-2021-35', 'Ruben', '08/03/2022 09:42'),
(54, 'Talent- en Innovatie Lab', 'Jared Wolffensperger', 'Melissa Finies', 'Hoog', '?', 'Jared Wolffensperger', 'Jared Wolffensperger', 'Jared', '-', 'Afgerond', 'In de bijlage heb ik de omschrijving voor de opdracht aan mediavormgeving toegevoegd.\r\n\r\nHet gaat om het ontwerpen van een logo en huisstijl voor het Talent- en Innovatie Lab, een logo en huisstijl voor de Crossovers, en een logo en huisstijl voor de verschillende pijlers onder het Talent- en Innovatie Lab.\r\n\r\nIk zal zelf fungeren als opdrachtgever.\r\n\r\nHet is de bedoeling dat er op korte termijn (in ieder geval voor Talent- en Innovatie Lab) een logo en huisstijl komt. Zijn er studenten die dit op kunnen pakken?\r\n2021-10-14: gaat vandaag ontwerpen opleveren \r\n2021-10-19: Jared. Dat is allemaal af. Factuur is nog niet verstuurd. Dit gaat hij morgen doen. Jared wist niet dat hij zijn factuur moest sturen, is nooit gezegd', 'Media', 'EM-2021-21', 'Tristan', '15/03/2022 01:33'),
(55, 'Lekker gewacht', 'Dylan Bouwhuizen', 'Provincie Zeeland', 'Normaal', 'Wouter Mahu', '-', '-', 'Dylan Bouwhuizen, Katja Willemse, Amber Middelkamp, Lana de Rijk, Teun Aardewerk', 'Dylan Bouwhuizen', 'Afgerond', 'Posters busplein - derde jaars MV opdracht (Vincent/Wouter)\r\n2021-28-09: akkoord op concept niet op offerte, gaat achter de offerte aan\r\n\r\n2021-10-05: Dylan. Vandaag oefen pitch gedaan en goedkeuring gehad. Morgen voor de klant ontwerp pitch. Daarna de volgende fase.\r\n\r\n2021-10-12: Dylan. Ontwerp pitch is gedaan. Ze gaan realisatie pitch doen donderdag.\r\n\r\n2021-10-19: Vanochtend is klant geweest. Eind deze week moeten we het laatste inleveren. Dan gaan we alles bespreken qua drukken enz. Liefst voor vakantie af, anders gaan we daarna verder\r\n\r\n2021-11-02: voor de vakantie oplevering gehad met de klant nog niet goedgekeurd, verwerken van ontwerpen deze week, kijken of donderdag iedereen klaar is en zo niet gaat Dylan de klant informeren en kijken hoe verder\r\n\r\n2021-11-09: Laatste oplevering gehad. Offerte moet nog nagekeken worden. Ruben in cc zetten\r\n\r\n2021-11-30: wacht een mailtje van de klant af voor het goedkeuren van de documenten\r\n\r\n2021-12-07: morgen met de klant de posters ophangen.\r\n\r\n2021-12-16: De klant moet alleen nog betalen, hij heeft aangegeven dat dit geen probleem is en dat hij dit gewoon gaat doen!\r\n\r\nDylan moet even heeeeeel snel bellen!', 'Media', 'EM-2021-18', 'Amber', '08/11/2022 11:35'),
(56, 'IVS Meeloop portaal', '-', 'Jessica Asaad', 'Laag', 'Cees-Jan Berman', '-', '-', '-', '-', 'On Hold', 'Is als examenproject door Sam Tieman gestart maar niet afgerond.\r\n\r\n2021-10-12: Morgen is de oplevering. Hij is bezig met documentatie voor volgnede sprint. wie?\r\n\r\n2021-10-12: yari Alles verloopt volgens schema. Leerofferte is opgestuurd.\r\n\r\n2021-11-02: niks geks loopt op schema \r\n\r\n2021-11-09: Hij loopt op schema. Morgen is de oplevering\r\n\r\n2021-11-30: Yari. Moet vervanging voor gezocht worden. Hij heeft de klant verteld dat hij van het project is, maar de klant weet nog niet of er vervanging komt. Yari moet even mailen met Ruben in CC.', 'Software', 'IS-2021-07', 'Amber', '08/11/2022 11:25'),
(57, 'M. Soundworks Portfolio Slideshow', '-', 'Evie Jongbloets', 'Normaal', 'Gerhard Hoogendoorn', '-', '-', '-', '-', 'Gestopt', 'Voor deze website: https://www.msoundworks.com/\r\nWil ik graag een custom plugin voor de portfolio page. Deze moet onder te verdelen zijn in verschillende categorien (film, commericeel, audio etc) en sorteerbaar op datum of bekendheid.\r\nIk wil de optie hebben een foto of video te uploaden + een audio fragment, met als hover-funtie dat de video of enkel geluid afspeelt.', 'Software', 'ES-2021-29', 'Ruben', '14/09/2022 10:01'),
(58, 'ADRZ', 'Kylian de kwant', 'Mandy van Oosten', 'Normaal', 'Wouter Mahu', '-', '-', '-', '-', 'Afgerond', 'Zij willen voor hun intranet animatievideo\'s waarin ze kennis of informatie kunnen delen met hun werknemers.\r\n\r\nm.vanoosten@adrz.nl \r\n\r\n05-04-2022: Morgen heeft hij initiatie gesprek.\r\n\r\n12-04-2022:  Morgen is de concept pitch. Hij heeft net zijn oefenpitch gehad, hij meot wat dingen aanpassen maar lukt wel .\r\n\r\n19-04-2022: Vorige week ontwerp pitch gehad. Hij maakt voorbeeld filmpjes en stuurd dit morgen naar de klant. Dit is de derde week van zijn sprint. \r\n\r\n10-5-2022 : Bezig met story board voor het filmpje. Hij heeft volgende week pitch, hij gaat het wel halen. \r\n\r\n\r\n17-05-2022 storyboard is af en ontwerppitch is in elkaar gezet, er is nog geen oefenpitch geweest. In overleg met coach (wouter) is dit enigzins goedgekeurd.\r\n\r\n31-05-2022 Hij is nog steeds bezig met zijn project, hij heeft in de tussentijd wel al een pitch voor de klant kunnen houden. Het filmpje kost wel veel tijd om aan te werken. Hij heeft het zelf best krap ingeplant. Hij weet dat hij de deadline van oplevering ( volgende week) niet gaat halen. Hierover gaat hij contact op nemen met de klant.\r\n\r\n07-06-2022: Pitch is verzet naar 22 juni omdat er meer tijd nodig was. 2 weken extra realisatie. Maakt filmpje af in de 2 extra weken.\r\n\r\n14-06-2022: voice over moet alleen nog gedaan worden. Colin doet voice over. meetings staan vast\r\n\r\n21-06-2022 Voice over is klaar. Alleen de fragmenten moeten nog worden gecontroleerd, omdat ze te lang duren of haperen. Hij levert het filmpje zelf op maar zonder audio dit wordt later er nog aan toegevoegd. Met een betere versie van de audio.\r\n\r\n28-06-2022: Hij is bezig met de voice over, heeft in de tussentijd nog wel een oplevering gehad hier nog wat kleine feedback op gehad. Hij heeft alleen nog realisatie pitch staan.\r\n\r\n08-07-2022: project is klaar, er moet opnieuw voice over gedaan worden. als dit is goed gekeurd kan er een factuur opgestuurd worden.', 'Media', 'EM-2022-07', 'Ruben', '07/09/2022 13:33'),
(59, 'Kunveni', 'Korben de Vos', 'Jeroen en Sofie Leenknecht', 'Normaal', 'Wouter Mahu', '+31 6 10012548', 'j.leenknecht@kunveni.nl', 'Amber Middelkamp, Korben de Vos ', 'Amber Middelkamp', 'Afgerond', 'Goede avond, \r\nWij zijn reeds enkele jaren bezig met onze VOF naast onze eigen banen. In de toekomst willen we meer vanuit de VOF gaan doen en daarom willen we graag een huisstijl laten ontwikkelen voor Kunveni met daarbij een website. Omdat wij pas over 1,5 tot 2 jaar echt volledig over willen gaan naar Kunveni is het bouwen van een website nog niet meteen een must. \r\nGroeten Jeroen en Sophie\r\n\r\nj.leenknecht@kunveni.nl\r\n0610012548\r\n\r\n2022-01-26: er is afgesproken eerst de huisstijl te maken, later de website pas.\r\n\r\n2022-03-11: Amber is de offerte aan het maken.\r\n\r\n15-03-2022: Offert is ondertekent. Ze is bezig met doel en doelgroep onderzoek. Planning moet ze in teams zetten. \r\n\r\n29-03-2022: Ze is zo goed als klaar met concepten dus gaat ze gaat pitches inplannen. Ze heeft gemailt met een voorstel vanochtend voor de pitch.  Waarschijnlijk is ze de week na haar dealine klaar. \r\n\r\n05-04-2022: Ze gaat om 1 uur pitchen vandaag. Concept pitch aan de klant. De klant reageert slecht, dus zegt Ruben dat ze zo veel mogelijk moet vragen zo meteen. \r\n\r\n12-04-2022: Er is voor een concept gekozen. Ze twijfelde over de kleuren. Nu gaat ze uitwerken. Buiten de vergadering gaan ze samen zitten voor de planning.\r\n\r\n19-04-2022: Morgen ontwerp pitch met de klant. Ze moet nog beetje feedback verwerken. \r\n\r\n10-5-2022:\r\nZit in de realisatie fase, gaat een afspraak maken voor vrijdag. De klant moet nog wat informatie verschaffen. \r\n\r\n17-05-2022 Gisteren realisatie pitch gehad goedkeuring gekregen van klant, nu alleen nog even alles klaar maken voor oplevering.\r\n\r\n13-06-2022: huisstijl is klaar, nu moet de website nog gemaakt worden\r\n\r\n05-10-2022: Hij heeft kleine functionaliteiten aangepast, hij heeft hierop al gelijk feedback gekregen. Hij heeft verder akkoord op sprint offerte en plan van aanpak gekregen. Coaches moeten hierover nog worden ingelicht.\r\n\r\n18-10-2022: Factuur is verstuurd, ze krijgen nog geen inloggegevens pas als de factuur is betaald. Ze waren akkoord met (F?)TO.\r\n', 'Media & Software', 'EX-2022-02', 'Amber', '18/11/2022 11:16'),
(60, 'Slimme plant project', '-', 'Steef van de Gruiter', 'Laag', 'Cees-Jan Berman', '-', '-', '-', 'Colin van der Ende', 'On Hold', 'Planten in de ruimte hebben een water sensor. Deze geeft informatie door aan een Raspberry Pi. De RP zet de informatie door naar een server.\r\n\r\nOp de server draait een website die de informatie bijhoudt. Ook kunnen drempelwaarden (Thresholds) ingesteld worden. Wanneer de waarde  (droogte) wordt overschreden krijgt een gebruiker een melding dat er water gegeven moet worden.\r\n\r\nDe tijd dat meldingen elkaar op moeten volgen en dat metingen gedaan moeten worden moet via de server kunnen worden ingesteld.\r\n\r\nDit is een KZD en AMO project (KZD Special IO en Embedded design) en wordt in periode 2 (Sprint 3 en 4) uitgevoerd als examenproject in samenwerking met een N23 student.\r\n2020-1-8: KBS -Is op dit moment nog bezig met de documentatie - is nu bijna klaar met PVA, examenofferte moest aangepast worden.\r\n2020-1-14: KBS - Raspberry heeft een functie om de connectie tussen de sensor en de rapsberry te lezen.In Python moet je deze functie toepassen en die is er niet. Colin kan geen connectie maken tussen de sensor en de raspberry, hierdoor kan hij niks aantonen. - Gerhard weet hier nog niets vanaf. Colin heeft het niet binnen de opleiding gevraagd.\r\n2020-8-26: GH - Project is niet afgerond. Klant zou graag een herinitiatie willen om hier wel mee verder te gaan (KZD Special IO en Embedded design project) \r\n\r\nWas examenproject colin is niet gelukt\r\n2021-10-19: ruben vraagt aan gerhard\r\n2021-11-04: wachten op nieuw examenkandidaat met special IO en embedded design.', 'Software', 'ES-2019-33', 'Tristan', '22/09/2022 13:19'),
(61, 'Meeloopplugin', '-', 'Gerhard Hoogendoorn', 'Laag', 'Cees-Jan Berman', '-', '-', '-', 'Katy Woud', 'On Hold', 'Offerte - loopt achter, teveel user stories. Doc klaar - over geslagen. - \r\nKritieke dingen werken niet - nog 2 weken. Permissions is een probleem. - Femke navragen nieuwe deadline. \r\nIssue lijst oplossen met Gerhard (Tijdens gesprek) - deze sprint minimale punten afmaken zodat versie online kan. 29-10-19 (Na sprint 3 gebruikers klaar)\r\n2019-11-01 : GH - Eerste versie werkt en wordt deze sprint opgeleverd. Evt later nieuwe project aanvraag voor door ontwikkeling.\r\n20210909 Wordt misschien vervangen door LOB Intergrip site\r\n2021-10-12: ruben vraag aan gerhard\r\n2021-11-04: Gerhard laat weten of het LOB systeem voldoende functionaliteit', 'Software', 'IS-2019-10', 'Tristan', '22/09/2022 13:18'),
(62, 'Meet2Learn redesign', 'Nick Vinke', 'Gerhard Hoogendoorn', 'Normaal', 'Sander Bruggeman', 'Nick Vinke', 'Melissa Janse', 'Nick, Melissa', 'Dennis Kerckhaert', 'On Hold', 'Issues:\r\nAls mail verstuurd word komt dit van meet2learn.info (Dit moet eruit) - komende week\r\nAsap een project aanvraag formulier en coach / leerling aanmeld module\r\nDaarna projectenpagina\'s ook met klanten project pagina - Testplan moet nog gemaakt, imp is af - oplevering nog afspraak - Lisa implementatie verkeerd overgedragen - Uitstel. - Donderdag nieuwe IMP\r\nVorige oplevering hectisch, CAPTCHA werkte niet, plugin kapot. - nieuwe plugins deze sprint (2)\r\n\r\n2019-11-01: GH - Project fase 1 opleveren deze sprint evt. even stop zetten als b\r\nezetting er niet is.\r\n2019-11-20: KBS - Begin realisatie - plug-in projectmanagement plug-in.\r\n2019-11-27: KBS - Vandaag testen - loopt op schema, Nick zijn plug-in is af. \r\n2020-1-8: KBS - Nog oplevering plannen.\r\n2020-1-14: KBS -Loopt achter, iedereen had een eigen ding en heeft niet aan project gewerkt. - Na vandaag lopen ze op schema.\r\n2020-3-10: documenten nog niet goedgekeurd door gerhard en realisatie loopt ook nog niet goed ( project genoten zijn steeds ziek )\r\n2021-10-12: ruben vraagt aan gerhard\r\n2021-11-04: bespreken met het bestuur', 'Software', 'ES-2018-38', '-', '-'),
(63, 'MDPS systeem', '-', 'Johan Elzinga', 'Normaal', 'Owen Vermeulen', 'Owen Vermeulen', 'Owen Vermeulen', '-', 'Owen Vermeulen', 'On Hold', 'Een app die gebruikt kan worden door mensen met een metaaldetector.\r\nOwenVermeulen heeft een eerste versie gemaakt.\r\nMoet opgepakt worden door een student die het keuzedeel Mobile App doet\r\n2021-10-12: word mischien opgepakt door Jeffrey\r\n\r\ninfo@metaalzoekworkshop.nl', 'Software', 'ES-2021-11', '-', '-'),
(64, 'Bestickering Ford Transit', 'Colin de Frel', 'Remco Ultee', 'Normaal', 'Jesse Vermeer', 'Colin de Frel', 'Colin de Frel', 'Colin de Frel', 'Colin de Frel', 'Afgerond', 'We wensen een ontwerp voor de bestickering van een antraciet busje: https://www.gpas-cache.ford.com/guid/40222329-29cd-31cd-b983-e89944101cb5.png\r\nVermelding van website: http://www.ultility.nl\r\nVermelding van bedrijfsnaam: ULTILITY\r\nVermelding van telefoonnummer: 0117308311\r\nVermelding van diensten: Computers - Webdesign\r\nDe bestickering mag achterop en aan de zijkanten, de lay-out mag subtiel zijn, voorbeeldje:\r\nhttps://www.advertizereclame.nl/wp-content/uploads/2021/06/auto-stickers-lierop-someren-berkvens-techniek-01.jpg\r\nEventueel kunnen er nog icons gebruikt worden, vb.: https://icon-library.com/icon/it-icon-19.html\r\nHuisstijl kunnen we doormailen.\r\n\r\nremco@ultility.nl\r\n0651680309\r\n\r\n29-03-2022: Hij heeft maandag initiatie gehad. Hij gaat deze week zijn concepten laten zien aan de klant. Hij heeft nog een ander projectje van jesse gekregen. dus zijn concept pitch is dinsdag ipv maandag. Is al ingepland\r\n\r\n21-06-2022: Zo goed als klaar, remco heeft nog niet de formaten doorgegeven aan collin. Dit heeft hij in de tussentijd zelf gedaan dus ze gaan hiervanuit verder en communiceren dit later nog met de klant. \r\n\r\n28-06-2022:Heeft stickers gemaakt, en doorgestuurd. Wacht nu op klantencontact en akkoord. zodat hij dit verder kan afronden. Hij gaat waarschijnlijk telefonisch contact zoeken. \r\n\r\n08-07-2022: wat bestanden nog opsturen en nog de factuur', 'Media', 'EM-2022-11', 'Ruben', '10/10/2022 16:21'),
(65, 'Amitable', 'Yannick Elias', 'Chantal', 'Normaal', 'Cees-Jan Berman', 'Yannick Elias', 'Yannick Elias', 'Yannick, Yoran, Oktay', 'Jeffrey Scheffers', 'Gestopt', 'Naam: Chantal\r\nEmail: chantal.amitable@gmail.com\r\nTelefoonnummer: 0032493466055\r\nAdres: SCHOUWBURGPLEIN, 4/0041\r\n\r\n12-11-2021\r\nProjectnaam: AMITABLE\r\nUitleg project\r\nHallo, wij hadden graag een app laten ontwikkelen voor volgend project.\r\nMet Amitable willen wij een toegankelijk en transparant online platform creÃ«ren voor een offline community,\r\nDe opzet is om het dagelijks koken en eten op je eentje te doorbreken door mensen samen te brengen die elkaar thuis uitnodigen\r\nen ontmoeten waardoor dagelijks eten terug een fijn moment van gezellig samen tafelen met een leuke babbel in een ongedwongen sfeer wordt\r\n\r\n2021-11-30: Jeffrey. 7dec initiatie.\r\n\r\n2021-12-07: initiatie is vandaag gehad, goed verlopen. Notulist maakt morgen digitaal de notulen aan. wordt vrijdag geleverd, aan de klant\r\n\r\n15-02-2022: Hij is bezig met systeem definieren. Morgen of donderdag wilt hij daar klaar mee zijn. Dan gaat hij gesprek inplannen met Gerhard over de mail.\r\n22-02-2022: Vrijdag meeting online met de klant. Native app of pwa gaan ze bespreken. Initiatie is al geweest, maar hij gaat definieren. \r\n02-09-2022: yannick heeft gisteren met zijn project lid contact gehad. Hij is onderzoek aan het doen naar verificatie methodes. De klant heeft een dure methode, Yannick geeft aan dat hij dat misschien wat goedkoper maar toch ook sterk kan.\r\n15-03-2022: Drama zegt hij . Het loopt achter op planning, door hij zelf en klant. Hij heeft het onderschat zegt hij. Jop lukt veel niet dus moet hij zelf redelijk veel. Ze vroegen aan de klant duidelijk logo en kleuren en dit is beetje vaag van de klant. Ze hebben hierdoor besloten media vormgever toe te voegen om de ontwerpen te maken, omdat hun ontwerpen niet goed waren. Hij heeft als kosten â‚¬50,- gezegd tegen de klant voor de media vormgever. \r\n22-03-2022: Druki bezig met realiseren. Iets meer dan de planning. Ze hadden te weinig om een goede oplevering te doen dus hebben ze extra dingen opgepakt. Dit kwam omdat ze media vormgever hebben ingeschakeld. Volgende week kunnen ze hopelijk de echte look op de site zetten. Hosting moet hij z.s.m. oppakken. Hij gaat de klant sturen of ze volgende week tijd heeft voor een meeting. \r\n\r\n29-03-2022: Oplevering ingepland, volgende week vrijdag. Hij gaat gelijk al alles regelen voor de volgende sprint. Momenteel is hij puntjes op i aan het zetten voor de realisatie en hij  is aan eh testen. Volgende sprint willen ze beginnen aan verificatie, Kost redelijk veel geld. Ruben zegt dat ze er een einde aan moeten maken, omdat het al lang niet opgelost is. Ze moeten gewoon kiezen of we doen het niet of we doen het wel. Hij moet alles wat hij weet aan de klant vertellen en niks anders voorstellen omdat ze dit van begin af aan al wilt. \r\n\r\n05-04-2022: Vandaag begonnen aan documentatie. Plan van aanpak is klaar, functioneel bijna klaar. Sprint offerte is ook bijna af. Vorige vrijdag is klant gesprek geweest. Klant was vast beraden en wilde dat doen. Woensdag is zijn oplevering. \r\n\r\n12-04-2022: Hij loopt op planning. Er waren kleine aanpassingen voor de documentatie. Hij moet ze goed laten keuren morgen. Morgen technisch ontwerp gesprek met Gerhard. Antonie geeft feedback op Yannick. Na de vergadering heeft hij project bespreking met Gerhard.\r\n\r\n19-04-2022: Hij loopt beetje achter. Nieuwe ontwikkel methode is lastiger dan hij denkt.  Hij is bezig met omzette van laatste applicaties. Hij had nu al alles omgezet moeten hebben en de user story\'s af hebben.\r\n\r\n17-05-2022 vorige week oplevering gehad, alle documentatie is af. Dingen zijn besproken die vorige sprint niet af waren. Voor de 23ste wordt dit wel opgeleverd. Aan het einde van de sprint zal er ook nog een oplevering zijn. \r\n\r\n31-05-2022 Vorige week een tussentijdse oplevering gehad, omdat hij de sprint daarvoor niet alles had opgeleverd. De oplevering liep soepel en goed, er zijn ook nog wat goeie punten bijgekomen. En ook nog wat eisen en wensen zijn er bij gekomen. Ze zijn nu alles aan het bekijken hoe ze alles kunnen doornemen en er in verwerken. Pas daarna gaan ze contact opnemen met de klant over hoe dat ze alles gaan verwerken. De user stories die vorige sprint niet af waren zijn nu wel afgerond. De deadline staat nu voor oktober. Er is wat achterstand ontstaan door gebrek aan kennis en gebrek aan wensen van de klant.\r\n\r\n07-06-2022: Laatste user story van vorige sprint is nu afgerond en zijn bezig met nieuwe user stories omdat klant aangaf dat er niet veel gebeurd was. Gaat gesprek inplannen hoopt voor volgende week. (Gaat over stand van zaken). Klant verwacht te veel.\r\n\r\n14-06-2022: meeting ingepland volgende week dinsdag voor oplevering. al begonnen aan documentatie voor volgende sprint. Mocht de klant stoppen en de bestanden willen worden de opleveringskosten gerekend. Factuur is gemaakt en wordt na de oplevering gestuurd.\r\n\r\n21-06-2022: Vanochtend oplevering en klanten contact gehad. Gaf aan dat er bepaalde eisen niet haalbaar waren met de eindoplevering datum. Ze gaan nu proberen een deel van de admin te realiseren, dit voor oktober te doen.  Ze gaan een nieuw plan opstellen en gaan dit communiceren met de klant. \r\n\r\n28-06-2022: Voorlopig geen problemen Loopt netjes op schema. Oktay heeft enige problemen met zijn laptop en de software. Dit loopt niet heel soepel maar is waarschijnlijk wel snel opgelost. Eindoplevering staat voor Oktober. Hij heeft een kleien planning gemaakt voor de klant over hoe hij nu zijn tijd gaat besteden aan het project. Hier heeft hij nog geen reactie op gehad. \r\n\r\n08-07-2022: Loopt een beetje achter vanwege een export functie, Heeft maandag 11 juli oplevering maar hoopt het vandaag nog recht te kunnen trekken.\r\n\r\n05-10-2022: Hij heeft het project verder opgepakt. Hij loopt tegen wat kleine puntjes aan die hij nu gaat proberen op te lossen. Hij gaat dit met de klant bespreken over hoe dat ze dit eventueel verder kunnen oplossen. \r\n\r\n2022-10-11: Eindoplevering ging goed, klant is van mening dat het stoppen van het project onredelijk is. Er wordt besproken hoe we eventueel nog wel verder zouden kunnen met dit project.\r\n\r\n2022-10-11: Het project is stop gezet omdat de eisen van de klant onredelijk werden.', 'Software', 'ES-2021-31', 'Ruben', '11/10/2022 13:16'),
(66, 'Hoekse Rakkers', 'Rick van Tilburg', 'Mirjam van de Wege', 'Normaal', 'Gerhard Hoogendoorn', 'Rick van Tilburg', 'Rick van Tilburg', 'Rick van Tilburg', 'Joost Kools', 'Afgerond', 'Na oplevering van het examenproject van Sean Kyle voor Speelweek Hoek hebben wij de volgende uitbreiding voor de geleverde website:\r\n- Overzicht foto AVG informatie (wel of niet mogen posten op facebook).\r\n- Overzicht allergene informatie\r\n- Email verificatie - controle of email van persoon is (correct is)\r\nEventuele extra functionaliteiten die tijdens in gebruik name naar boven komen.\r\n2019-11-19: KBS - Examen project, hierdoor hogere prioriteit.\r\n2019-11-20: KBS - TO en FO opsturen - nog naar betaling kijken. Gaat volgens Bryan \'Wel goed\'. Project naam heet nu \'Hoekse Rakkers\'.\r\n2020-1-8: KBS - Tussenoplevering, maandag erop is de eind oplevering.\r\n2020-1-14: KBS - Komende dagen optimaliseren en tickets oplossen, site is geï¿½mplementeerd. Volgene sprint vormgeving, komende vrijdag na-oplevering - acceptatietest.\r\n2020-3-10: bijna alles af voor de oplevering, plug-in nog niet af zijn grote problemen gevonden door een externe hij gaat tycho gaat morgen en overmorgen samen zitten om dit op te lossen en lukt dit niet zal de plug-in opnieuw gebouwd moeten worden\r\n2020-9-15: Vanochtend heb ik contact gehad met de klant van Hoekse rakkers en er is besloten dat de projectdoelen gehaald zijn\r\nOp een kleine ticket na die ik op ga lossen. (Hier hoef je dus geen zorgen over te maken)\r\nIn de tussentijd hebben ze meer gevonden om te laten doen op de website en zouden graag het project door laten lopen,\r\nHiervoor zal een nieuwe initiatie nodig zijn en zal het dus op worden gepakt als een nieuw project.\r\nMijn vraag aan jou kan je dit project op de projectenlijst naar status initiatie zetten en zorgen dat deze z.s.m. opgepakt wordt,\r\nAlvast bedankt.\r\n\r\nMet vriendelijke groet,\r\n\r\nTycho \r\n2021 juni 21 : Joost Kools zou dit afgerond hebben: Klant bellen.\r\n2021-28-09: niet aanwezig\r\n2021-10-05: Er waren nog een paar dingen die aangepast moeten worden. Tycho wacht op mail van haar.\r\n2021-10-12: wachten op klantmail met de laatste beetjes\r\n2021-10-19: klant heeft gereageert, nu moet er iemand nieuw gevonden worden om dit op te pakken\r\n\r\n02-22-2022: rick heeft het project weer opgepakt, hij heeft nu een paar tickets opgelost en zal volgende sprint beginnen met documentatie\r\n\r\n15-03-2022: Documentatie is bijna af. Oplevering is 1 april. Vandaag gaat hij een mail sturen om samen te zitten voor documentatie. Vorige week was hij ziek daarom loopt hij beetje achter. Zaterdag gaat hij realiseren, zo trekt hij het recht.\r\n\r\nRealisatie is af. 1 april is de oplevering. Documentatie is volledig. Straks gaat hij met Korben de code review doen. Morgen gaat hij test personen regelen. Donderdag testen en verslag maken. Er moet geen oplevering betaald worden, wel de sprints, omdat het een stichting is. \r\n\r\n29-03-2022: Realisatie, zeltesten zijn af. Acceptatie test gaat hij bij oplevering doen. Uit testresultaten is 1 fout gebleken. Ruben zegt dat hij de acceptatie test eigenlijk eerder moet doen. Vrijdag is de oplevering. \r\n\r\n05-04-02022: AFgelopen vrijdag oplevering gehad. FActuur is opgestuurd, gisteren. Hij gaat onderzoek doen voor een betaal methode, is vandaag opgestuurd. Persoonlijke leerofferte maakt hij vandaag. Hij loopt op planning. Hij heeft vrijdag een gesprekje. \r\n\r\ndocumentatie ondertekent, realisatie begonnen. vrijdag 13 mei. \r\n\r\n19-04-2022: Realisatie is klaar. Testen nu. Klant is tevreden. Misschien komen er een paar kleine tickets. Of als hij tijd over heeft doet hij dat. Factuur sprint 9 is nog niet betaald.\r\n\r\n31-05-2022 Vorige sprint oplevering gehad, penningmeester was er niet bij dus die functie is niet getest. Die wordt vrijdag met de penningmeester getest. \r\n\r\n14-09-2022: factuur is betaald en project is afgerond.', 'Software', 'ES-2019-26', 'Tristan', '21/11/2022 20:36'),
(67, 'Webshop Hondenschool', 'Jaimy Zegers', 'Henry Weesie', 'Normaal', 'Vincent Brunings', '+31 6 234 472 10', 'info@hondenschool-heikant.nl', 'Nick Kroezen, Miko de Meijer, Jaimy Zegersklhjasflijashdlfkjhaslkdfjhalskdjfhalksjdhflaksjhdflakjshdflkajshdflisa', 'Roxanne van Hulle', 'Bezig', 'i.o.m. Johanna Dieleman bij jullie terecht gekomen:\r\nIk ben geinteresseerd in een webshop waarbij niet het product rechtstreeks gepromoot wordt maar waarbij klanten kunnen zoeken op een probleem dat ze opgelost zouden willen zien en waarvoor ik een product aanbied. Bijvoorbeeld \'Veelvuldig blaffen\' met als product bijvoorbeeld \'antiblafspray\'. Ik zou daarbij zelf in staat willen zijn om het probleem met enkele woorden te omschrijven, in een dieper niveau het probleem uitgebreider uitleggen met de oplossing in de vorm van een product.\r\n\r\n12-10-2021: klaar om te starten.\r\n\r\n22-03-2022:  Heeft initiatie gehad,2 weken geleden. Begonnen aan documentatie en zijn user story\'s aan het oppakken.\r\n\r\n10-5-2022: Net een oplevering gehad. was miscommunicatie met de klant. Er zijn afspraken gemaakt voor de volgende sprint.\r\n\r\n17-05-2022 oplevering was goedgekeurd, begint aan nieuwe sprint. \r\n\r\n31-05-2022 Start van de sprint waren ze een beetje verdwaald binnen dit project, ze zijn nu bezig met het realiseren van dit project. Ze gaan nu kijken wat ze verder kunnen doen om het project af te ronden.\r\n\r\n07-06-2022: Zijn de weg een beetje kwijt. Online omgeving loopt mis uiteindelijk wel opgelost. Binnenkort meeting klant. Volgende week dinsdag meeting.\r\n\r\n14-06-2022: Klantgesprek gehad, bleek dat er niet genoeg doorgevraagd was waardoor er geen hosting was. Kon niet doorgewerkt worden omdat er een groot deel online gedaan moest worden. \r\n\r\n21-06-2022: Gesprek met de klant gehad, ze is nu bezig met concepten te bedenken en al wat uit te werken. De mensen op dit project lopen tegen het probleem aan dat er bepaalde gegevens van Strato ontbreken. Zonder deze gegevens kunnen zij niet verder. \r\n\r\n28-06-2022: Designs van Katja zijn goedgekeurd op haar concepten. en gaat deze nu uit te werken in de ontwerp fase. Iets meer achterstand opgelopen ivm ziekte en verzuim van Nick. Dit kan nog wel even duren.  Er is misschien iemand extra nodig op dit project, alleen op dit moment zijn alle studenten bezet. \r\n\r\n05-10-2022: Documentatie is afgerond, nick en miko zouden voor de rest het project verder oppakken alleen zijn deze afgelopen week afwezig geweest. \r\n\r\n18-10-2022: Morgen oplevering, realisatie is goed gegaan. \r\n\r\n1-11-2022: hij heeft contact gemaakt met de klant voor de volgende meeting in te plannen.\r\n\r\n08-11-2022: Heeft vorige week donderdag een mailtje gestuurd naar klant voor een meeting. Deze was voor nu wel verkeerd ingepland op een studiedag, hier moet dus nog even naar gekeken worden. \r\n\r\n22-11-2022: Heeft nu oplevering.\r\n\r\n7-12-2022: Documentatie is gemaakt, ze gaan nu gewoon verder met het project. Werk is goed verdeelt, ze hebben allemaal genoeg bezigheden. \r\n\r\nAdres: Magdalenastraat 30 Heikant', 'Software', 'ES-2021-15', 'Dylan', '07/12/2022 11:50'),
(68, 'Van Damme - bedrijfs fotografie', 'Wouter Mahu', 'Thomas Leegwater', 'Hoog', 'Wouter Mahu', '-', '-', '-', 'Katy Woud', 'In Afwachting', 'Mijn klant van \'Van Damme c.s. Gerechtdeurwaarders\' wilt graag dat IVS nieuwe foto\'s maakt bij hun op locatie. \r\nVorige keer is dit niet zo goed gegaan dus daarom willen we dat het op de projectenlijst komt als opdracht. \r\nHet liefst zouden er mensen op het project moeten komen die al wat ervaring hebben met fotografie, belichting en sluitertijd. Klant \r\nis Arnold van Damme maar de contactpersoon is Thomas Leegwater, net zoals bij de website. \r\nMet Florenz opnemen en uit laten voeren.\r\nWacht nu ivm Corona beperkingen.\r\n2021-10-12: dit gaat wouter oppakken met een paar 1e jaars\r\n\r\nThomas@vandamme-holland.nl', 'Media', 'EM-2020-02', 'Tristan', '22/11/2022 21:49'),
(69, 'Klanten database', '-', 'Rosita van Geersdaele', 'Hoog', 'Wouter', '-', '-', '-', 'Nick Vinke', 'Gestopt', '2020-5-12: \r\nBeste,\r\nIk ben de moeder van Jaimy Zegers (student applicatie en mediavormgeving). Daardoor kwam ik op het idee om contact met jullie op te nemen, hoewel ik er helemaal niet zeker van ben of jullie mij kunnen helpen.\r\nIk heb een praktijk voor lichaamsgerichte therapie/coaching en ben al een tijdje op zoek naar een systeem/ database voor mijn cliï¿½ntgegevens. Het liefst met de mogelijkheid aan dit systeem facturen te koppelen, evt een online agenda te koppelen of zelfs een digitaal dossier te koppelen.\r\nGraag hoor ik van jullie of deze vraag hier op zijn plaats is en of jullie daar iets mee kunnen.\r\nAlvast bedankt!\r\nVriendelijke groetjes,\r\nRosita van Geersdaele\r\nVeerstraat 15\r\nZaamslag\r\n2021-02-09 GH: 15-1-2021 Initiatie gesprek gehouden en door klant goedgekeurd.\r\n2021-10-12: vraagt ruben aan gerhard\r\n2021-11-04: klaar om te starten\r\n\r\n\r\nrvgeersdaele@zeelandnet.nl', 'Software', 'ES-2020-12', 'Ruben', '15/09/2022 10:52'),
(70, 'EU Rotating BV website', 'Sam de Kock', 'Artan Mulleti', 'Normaal', 'Cees-Jan Berman', '-', '-', '-', 'Korben de Vos', 'Initiatie', 'Website vernieuwen EU Rotating bv. Met de website willen we de verbetering van onze diensten aan de klant laten zien zodat zij een beter beeld hebben van wat wij doen.\r\nWat EU Rotating precies doet is werkzaamheden uitvoeren in de rotating omgeving zoals: gasturbines, stroomturbines, generatoren, gearboxes,pompen,ventilatoren,enginering, hogeredruk flenzen,Industriele service,Technical support service supervisie tc. Uiteindelijk zal deze website in het Engels moeten worden geschreven omdat EU Rotating werkt zowel als in het binnenland en in het buitenland.\r\n\r\namulleti@eu-rotating.eu\r\n0653554195\r\nWebsite: http://www.eu-rotating.eu\r\n\r\nproject is klaar te starten, als de klant tijd heeft.\r\n\r\n21-09-2022: contact geweest met klant, heeft voorlopig geen tijd. Gevraagd of hij een mailtje wil sturen zodra het project wel gestart kan worden. Sam heeft met hem gebeld.', 'Software', 'ES-2021-36', 'Amber', '04/11/2022 14:15'),
(72, 'Cyber Security', 'Antonie de Jong', '?', 'Normaal', 'Gerhard Hoogendorn', '-', '-', 'Nick kroesen, Damian van den Sluis', '-', 'Afgerond', 'Gerhard verteld dat er een nieuwe project komt binnen kort. Dit is voor twee personen, volgende sprint begint dit. Het is meer een SD project. Een stagiaire moet mee in het project en een IVS lid, dat lijkt Gerhard het beste. Het gaat om security. \r\nVolgende week gaat Gerhard ermee samen zitten en wilt Tristan erbij zitten.  \r\n15-03-2022: Vrijdag gesprek gehad met klant. Voor 1 april leeroffrte maken. ZE gaan samen praten over hoe de leeromgeving in te richting. Donderdag spreken ze af, ze gaan dan een lijst uitwerken. Hij heeft nog geen planning in teams gezet. \r\nRuben moet dit aanpassen naar cross over project. \r\n\r\n22-03-2022: Vandaag hebben ze samen gezeten.  Op 1 april hebben ze oplevering. Ze zijn aan het kijken van welke bedrijven ze erbij kunnen betrekken. Ze gaan volgende week dinsdag langst bij een frietfabriek. Zodat er misschien een opdracht uitkomt. Ze hebben al een lijst van 10 bedrijven die zeggen dat ze al mee willen doen. \r\n\r\n29-03-2022:  Ze hebben bedrijven gevonden en hebben functioneel ontwerp gemaakt. Ze gaan binnenkort langst een bedrijf. Dit support software enz. Ze moeten een nieuwe leeromgeving maken. eerst word er een event gemaakt en een webinar. Hij heeft ook contact met provincie zeeland dit moment. Er moet eigenlijk eerst een plan van aanpak gemaakt worden zodat Ruben deze kan doorlezen en het meer snapt. Vrijdag 1 april is oplevering met de klant. \r\n\r\n05-04-2022: Plan van aanpak niet gemaakt. Omdat ze niet meer samen zijn gekomen. Morgen staat er een meeting gepland. Ruben gaat morgen apart zitten met hem. \r\n\r\n12-04-2022: Vrijdag klant gesprek gehad. Regelen van evenement besproken. Donderdag nieuwe afspraak gemaakt. Draaiboek moet dan gemaakt zijn. Plan van aanpak word door Damien gemaakt. Donderdag is de deadline van plan van aanpak. Ze werken niet met sprints, wel met scrum, Trello. \r\n\r\n19-04-2022: Hij zoekt een media vormgever voor een flyer. Donderdag klant gesprek. Morgen meeting met andere opleidingen en nog een paar andere mensen. \r\n\r\n10-5-2022: Donderdag initiatie gesprek gehad, ze zijn druk bezig met alles te regelen. Deze week verschillende meetings gehad met verschillende mensen die binnen dit project zitten.\r\n\r\n17-05-2022 Nick & Damian zijn beiden ziek dus er is niet echt veel vooruitgang voor deze week. Er staat een andere datum gepland voor dat gesprek, dit zou donderdag plaatsvinden. Vrijdag zou een oplevering zijn voor het draaiboek. De 31 ste staat een meeting gepland met iedereen van het project. \r\n\r\n31-05-2022 Wesley van Gou & Rico De Vos \r\n10 Juni is er een oplevering dus moet het project worden afgerond ivm een festival. Er wordt vandaag een mailtje gestuurd naar de projectleider hoe het project loopt. Nick heeft het draaiboek geschreven.\r\n\r\n08-07-2022: Retrospective is gehouden.', 'Software', 'IS-2022-07', 'Tristan', '08/07/2022 09:23'),
(73, 'Mystery box Logo', 'Timo Fieret', 'Jessica Asaad', 'Normaal', 'Wouter Mahu', '-', '-', '-', 'Timo Fieret', 'Afgerond', 'huistijl en een logo maken\r\n\r\nDeadline: 1 april\r\n\r\n22-02-2022: Vorige week is initiatie geweest. Deze week is hij met doelgroep onderzoek bezig en planning is gemaakt en gestuurd.\r\n\r\n29-03-2022: Hij heeft vrijdag pitch. Hij weet neit zeker of hij dat haalt, maar doet zijn best. Ontwerp pitch. \r\n\r\n05-04-2022: Hij heeft oefen ontwerppitch, morgen de normale ontwerppitch. Hij weet niet zeker of hij het gaat redden morgen. Voor komende projecten moet hij het beter bijhouden als het een echte klant was met een echte factuur.\r\n\r\n12-04-2022: Vandaag ontwerp pitch gehad. Akkoord gekregen. Huisstijl gedeelte overhet hoofd gezien, dus begint hij er nu aan. Realisatie is donderdag ingepland. Logo word opgeleverd voor de vakantie, huisstijl na de vakantie. \r\n\r\n17-05-2022 heeft realisatie pitch gehad, dit was voor het logo. Voor donderdag stond een pitch voor huisstijlhandboek gepland alleen was hij ziek. Dus er is een nieuwe datum gepland daarvoor. \r\n\r\n2022-06-13: project is afgerond, en er is afgesproken dat er geen betaling zou plaats vinden. hierdoor is het project afgerond\r\n', 'Media', 'IM-2022-08', 'Tristan', '13/06/2022 09:58');
INSERT INTO `project` (`id`, `projectnaam`, `projectleider`, `klant`, `prio`, `projectcoach`, `telefoonnummer`, `emailklant`, `projectleden`, `initiatieleider`, `project_status`, `opmerkingen`, `opleiding`, `administratienummer`, `bewerkt_door`, `bewerkt_datum`) VALUES
(74, 'Project management systeem (5.0)', 'Tristan Verschueren', 'Ruben Struijlaart', 'Normaal', 'Cees-Jan Berman', '+31 6 835 751 48', 'rstruijlaart@student.scalda.nl', 'Tristan Verschueren', 'Tristan Verschueren', 'Bezig', 'PMS is al in gebruik maar wordt verder ontwikkeld.\r\n\r\n05-04-2022: Hij heeft maandag initiatie gehad. Nu is hij bezig met documentatie samen met Norah. Morgen verstuurde hij de sprint offerte.\r\n\r\n12-04-2022: Documentatie is af. Begonnen met realisatie. van de week bijpraten met de klant en Gerhard. \r\n\r\n19-04-2022: Realiseren is bezig. Errors zijn opgelost. Oplevering is na de vakantie. \r\n\r\n10-5-2022: Het project loopt soepel. Er zijn al een aantal userstories af. Voor volgende week willen ze nog iets inplannen voor de klant. Woensdag 18 mei 2022 om 12:30 uur staat dit gepland met Gerhard.\r\n\r\n17-05-2022 morgen oplevering van deze sprint. De userstories die staan beschreven zijn af en zijn naar behoren. \r\n\r\n31-05-2022 Er is een oplevering geweest, er is ook geÃ¯mplementeerd, ze zijn nu bezig met de userstories deze zijn best groot. Documentatie is af.  Deze spint willen ze meerdere accounts er op zetten zodat er meer mensen bij kunnen.\r\n\r\n14-06-2022: Bezig met documentatie, PLO is af en ontwerpen moeten aangepast worden. Oplevering moet gepland worden.\r\n\r\n21-06-2022: Dit loopt goed, ze hebben een paar nieuwe dingen ontwikkeld. Van de week woe/ do staat een oplevering gepland. Dit is ook een deel van de vorige sprint. Daarna gaat hij gewoon verder aan deze sprint. \r\n\r\n28-06-2022: Heeft met de klant afgesproken dat de oplevering van vorige sprint wordt opgeschoven naar deze sprint. Dit kwam door wat kleine problemen. Nu wordt eigenlijk alles verder afgerond. \r\n\r\n\r\n05-10-2022: Hij is nog met de accounts bezig. Dit ligt iets buiten de oplevering. Hij gaat dit zsm. implementeren. \r\n\r\n18-10-2022: hij heeft de sprintofferte opgestuurd. Hij gaat de accounts opleveren/ zich mee bezig houden voor deze sprint. \r\nhierna gaat het project duurzame proeftuinen weer beginnen.\r\n\r\n1-11-2022: Hij gaat voor aankomende donderdag een meeting in plannen voor het gedeelte acounts op te leveren. Hij moet ook de documentatie op zien te leveren aan de klant. ', 'Software', 'IS-2021-38', 'Tristan', '13/11/2022 00:29'),
(75, 'Film Modeshow', 'Lana de Rijk', 'Veronique de Poorter', 'Normaal', 'Wouter Mahu', 'Lana de Rijk', 'Lana de Rijk', 'Lana de Rijk, Dylan bouwhuizen', 'Lana de Rijk', 'Afgerond', '26&27 maart doen wij mee met het modeweekend.\r\nHierbij zullen een 5 tal modellen onze nieuwste mode presenteren op een rode loper in de winkel. Dit alles in een gezellige ambiance met live muziek.\r\nNu zouden wij graag het professionele filmpje ook voor onze sociale media willen gebruiken.\r\nAangezien wij nog maar 1 jaar actief zijn kunnen we zeker wat extra promotie gebruiken tijdens deze lastige tijden.\r\nIk hoor graag jullie reactie.\r\nHet is wel bekend bij Lana de Rijck. Een leerling van jullie .\r\nVriendelijke groeten\r\nVeronique de Poorter van conceptstore Elle maakt je Blij\r\nHulst.\r\n\r\ninfo@ellemaaktjeblij.nl\r\n0615678785\r\n\r\n15-03-2022: Woensdag heeft ze intake. Ze moet het nummer van Merel aan veronique vragen\r\n', 'Media', 'EM-2022-09', 'Ruben', '13/05/2022 01:12'),
(76, 'Google spreadsheet automailer', 'Kylian de putter', 'Remco Ultee', 'Normaal', 'Cees-Jan Berman', '-', '-', 'Kylian de Putter', 'Mathieu heyndrickx', 'In Afwachting', 'Wij bieden onze klanten een APK+ abonnement aan, zie deze link voor iets meer info: https://www.ictartikelen.nl/product/apk-abonnement/\r\nNa een jaar dient de klant geÃ¯nformeerd te worden dat het weer tijd is voor een nieuwe APK voor hun computer. We hebben in Google Spreadsheet een lijst waarin de volgende gegevens zijn opgenomen:\r\nKlantnaam - Mail - Telefoon - Klantnummer - Startdatum - Verlengingsmail verzonden - Verlengingsdatum - Uitgevoerd per datum - Notities\r\nWe willen dat klanten (+ CC naar info@ultility.nl), al dan niet automatisch, een e-mail krijgen vanaf ons info@ultility.nl e-mailadres via bijv. Google script editor zeven dagen voor het verstrijken van de verlengingsdatum. De inhoud van de mail leveren wij aan, de mail dient dynamisch te zijn, hierin dienen o.a. de klantnaam, klantnummer, startdatum en verlengingsdatum in opgenomen te worden.\r\nDe kolom \"Verlengingsmail verzonden\" dient gevuld te worden met de datum waarop de e-mail verzonden is.\r\nUndelivered e-mails willen we op info@ultility.nl ontvangen.\r\nDe Verlengingsdatum moet op basis van de Startdatum of \"Uitgevoerd per datum\" automatisch wijzigen naar een jaar later (+365).\r\nDe opmaak van de e-mail moet in de Ultility huisstijl zijn. In het kader van AVG mag het uiteraard niet voorkomen dat klantgegevens gedeeld worden, dus elke e-mail dient apart verzonden te worden.\r\n\r\n12-04-2022: Gister een gesprek met Remco gehad. Laten zien wat hij had. Hij heeft een huisstijl gekregen. Documentatie is bijna af. Functioneel ontwerp op feedback verbeteren. Als dat af is verder met realiseren, dat is ook bijna af. \r\n\r\n19-04-2022: Documentatie heeft nog geen goedkeuring. Realisatie is bezig, vandaag klein probleem ontdekt, maar makkelijk op te lossen. Hij loopt op schema. \r\n\r\n10-5-2022: heeft een oplevering staan voor volgende week maandag. Hij liep tegen een probleem aan dit wil hij eind van de week of begin volgende week opgelost hebben zodat hij hierna verder kan. \r\n\r\n31-05-2022 Hij heeft wat vertraging opgelopen, nu heeft hij met Remco samengezeten. Hij gaat verder met de kennis die hij hiervan heeft meegekregen. Hij wil voor dinsdag wat dingen opleveren. Dit moet hij alleen nog even met Gerhard bespreken en Christian hierover inlichten dat hij niet aanwezig is. hierna na deze oplevering is het project klaar.\r\n\r\n07-06-2022: Vandaag oplevering, 3 kleine verbeterpunten. project zo goed als afgerond.\r\n\r\n14-06-2022: oplevering gedaan met een paar feedback puntjes. Feedback wordt verwekt voor nieuwe oplevering. Moet nog gepland worden\r\n\r\n\r\n21-06-2022: Gisteren oplevering voor de klant, geen fouten of feedback verder. Dit was een realisatie oplevering. Hij moet nu alleen nog een handleiding schrijven en implementatie plan opstellen. Daarna gaat hij de eindoplevering inplannen. \r\n\r\n28-06-2022: Vorige week oplevering, kleine foutjes. Paar documenten handleiding acceptatie plan etc heeft hij allemaal afgemaakt. Hij wil dit in een geheel opleveren aan de klant. ', 'Software', 'ES-2022-10', 'Amber', '04/11/2022 14:18'),
(78, 'Boom in beeld', 'Ibraim', 'Henk Visser', 'Normaal', 'Wouter Mahu', '-', '-', 'Ibraim', 'Timo en Jaimy', 'Gestopt', 'Onze bomenwerkgroep plaatst in ons eilandelijk blaadje regelmatig een interview met een bewoner. Het onderwerp is een favoriete boom.\r\nEr zijn nu zo\'n 18 stukjes geschreven, ik zou deze stukjes graag in een boekje uitgeven. Ten eerste in digitale vorm, in e-pub formaat. Ten tweede als dit haalbaar is als drukwerk.\r\nIk heb al een aantal stukjes gepubliceerd in ISSUU. Hier is de link https://issuu.com/home/published/bomen_in_beeld_1_t_m_8_door_agnes_tieben\r\nAls amateur ben je snel tevreden maar een vormgever weet er altijd iets mooiers van te maken. De schrijfster Agnes heeft er zo veel werk van gemaakt, het zou leuk zijn als zij nu een mooi boekje er voor terug zou krijgen.\r\n\r\n21-06-2022: Aankomende donderdag heeft hij gesprek met de klant, dat gesprek wilt hij meer informatie uithalen. Hij plant dat gesprek in en daarna gaat hij verder aan dat project werken.\r\n\r\n08-07-2022; Email gestuurd naar klanten en gezegd dat ze na de vakantie beginnen met het project i.v.m. korte tijd tot de zomervakantie.\r\n', 'Media', 'EM-2022-12', 'Ruben', '15/09/2022 10:17'),
(79, 'Animatie G.R.A.M. (Rebecca Boelens)', 'DaniÃ«l Willemkens', 'Rebecca Boelens', 'Normaal', 'Jesse Vermeer', '-', '-', 'Daniel Willemkens', '-', 'Factuur', 'Scalda is partner in een Europees project van Interreg samen met Syntra West Vlaanderen en Unizo West Vlaanderen. de partners beogen leeromgevingen rondom duurzaamheid, ondernemerschap, innovatie neer te zetten waarbij studenten werken aan echte opdrachten uit de regio. (het regioleren als uitgangspunt) Men beoogt een win-win situatie: bedrijven kunnen iets met de uitwerkingen en voor studenten is er een aantrekkelijke manier om te leren. De bedoeling is om aan andere docenten en andere scholen, bedrijven en andere geÃ¯nteresseerden de manier van dit onderwijs uit te leggen via een animatiefilm. De film geeft een beeld weer van het proces van de acquisitie van een opdracht, het voeren van een klantgesprek, wat de coach en de experts doen, wat er beoogd wordt dat de studenten aan skills ontwikkelen, de oplevering van een project.\r\n\r\nrboelens@scalda.nl\r\n0611156735\r\n\r\n29-03-2022: Vorige maandag initiatie gehad. Hij is begonnen aan de concepten. Hij gaat morgen zijn pitch maken en dan donderdag of vrijdag oefenpitch maken. Hij wilt volgende week pitchen met de klant.\r\n\r\n\r\n04-05-2022: Gister gesprek gehad. donderdag voor de vakantie is een meeting ingepland. \r\n\r\n12-04-2022: Het loopt hetzelfde. Gesprek is geweest. Hij is bezig met story boards. Hij gaat met de klant iets inplannen. Ontwerp pitch donderdag voor de vakantie. \r\n\r\n19-04-2022: Story boards zijn nu af gerond. Powerpoint is ook klaar. Vandaag zou de oefenpitch zijn, maar Jesse is ziek.  Waarschijnlijk kan het morgen met Wouter. Ontwerp pitch is donderdag met de klant. \r\n\r\n10-5-2022: Vrijdag voor de vakantie oefen pitch gehad, vandaag normaal de ontwerp pitch de klant was helaas verhinderd. Daarom gaat hij deze waarschijnlijk naar volgende week dinsdag of donderdag kan verzetten. \r\n\r\n17-05-2022 de klant kon vorige week niet voor de pitch, het contact liep niet heel soepel. Nu staat de afspraak voor op volgende week maandag, de coaches en iedereen zou kunnen. Hij liep wat achter maar nu met de geplande afspraak loopt hij weer op schema. \r\n\r\n31-05-2022 Vorige week maandag heeft hij oplevering gehad, hierover heeft hij nog feedback gehad van de klant. Dan gaat hij morgen nog wat dingen aanpassen en wat dingen ontvangen van de klant. Na dit kan hij aan het filmpje beginnen zodat hij deze kan gaan uitwerken. \r\n\r\n07-06-2022: Kan nog niet alles realiseren want verwacht nog een aantal documenten van de klant.\r\n\r\n14-06-2022: Hetzelfde als vorige week, gesprek moet nog gehouden worden maar er is mailcontact geweest. Donderdag wordt er een meeting gehouden met de tussenoplevering en daar kijken ze of er eventueel nog iets veranderd moet worden. Meeting staat vast. \r\n\r\n21-06-2022: Vorige week donderdag gesprek gehad met de klant, ze zou de teksten opleveren. Dit heeft ze nog niet gedaan. Ze heeft feedback gegeven over de storyboards. Dit was een totaal ander idee van het eerste plan. Hij kan beter de wensen en eisen nog een keer doornemen en dit ook laten ondertekenen. \r\n\r\n28-06-2022: Contact gehad met de klant over de storyboards. Dit was donderdag. Ze gaan samen nog een storyboard bekijken. Ze gaan nu kijken hoe ze met de animatie verder te gaan en dit verder af te maken. Dit is niet meer haalbaar voor voor de vakantie af te ronden. \r\n\r\n08-07-2022: Besproken vorige week wat de volgende stappen zijn. Hebben ervoor gekozen om gewoon na de vakantie verder te gaan.\r\n\r\n2022-10-10: Vrijdag meeting met Rebecca om het af te ronden.\r\n\r\n1-11-2022: De eindoplevering staat nu over twee weken. Dit ivm. het niet na komen van de afspraken vanaf de klant haar kant. De meetings staan al ingeplant. \r\n\r\n16-11-2022: realisatiepitch gehad, kleine aanpassingen nog (stukje animatie bij aftiteling, app-stukje wat dynamischer). Factuur liefst zsm sturen, op naam van Stichting G.r.a.m.\r\n\r\n29-11-2022 : Vorige week realisatie pitch gedaan voor de klant. Vandaag is het filmpje ook daadwerkelijk afgerond. Dus hierna is het project afgerond. Hij is aan het kijken voor zijn volgend project.\r\n\r\n7-12-2022: Feedback verwerkt van de realisatie pitch. Klant was erg tevreden over opgeleverd product. Hij heeft nog geen tijd gehad om voor een volgend project te kijken. Factuur is verstuurd, moet nog even worden gecontroleerd.', 'Media', 'EM-2022-13', 'Dylan', '07/12/2022 11:26'),
(80, 'Healthy Hair ', 'Jessica Asaad', 'StÃ©fanie van de week', 'Normaal', 'Jesse Vermeer', '-', '-', 'Damian van der Sluis', '-', 'Afgerond', 'Goedemorgen, ik ben een kleine ondernemer die net is gestart. Nu wil graag een website om mezelf professioneel te presenteren en een webshop om mijn producten te verkopen\r\n\r\nEmail: svandevisser@hotmail.com\r\nTel: 0628396765\r\n\r\n04-05-2022: Gesprek morgen. Samen met Damien gezeten voor teams vergadering. Morgen komt ze met haar man, er komen eerste jaars bij. \r\n\r\n12-04-2022:  Klant heeft documentatie gekregen. Ze hebben problemen met de mail, dus appen ze. Gister ochtend oplevering gehad. Morgen ochtend weer een oplevering. Haar feedback daarna verwerken. Einde van de sprint word het online gezet. Documentatie plan moet dan opgesteld worden. Ze gaan implementatie plan maken en kunnen na de vakantie implementeren. \r\n\r\n19-04-2022: Gaat goed. Tussen door paar keer opgeleverd. Maandag na de vakantie wilt ze weer een meeting houden. Daarna zijn ze bijna klaar.\r\n\r\n10-5-2022: Gisteren oplevering gehad, feedback ontvangen van de klant. Implementatie plan moet nog worden gemaakt. Over twee weken maandagen is het waarschijnlijk eindoplevering zijn. De klant heeft weinig tot geen idee van het gehele ontwerp. Hierdoor gaat ze nog een offerte sturen van 4 weken, omdat ze het vermoeden heeft dat het nog wat uit gaat lopen.\r\n\r\n17-05-2022 jessica is bezig met implementatie plan, als Damian beter is moet hij zelf daar ook nog aan werken. De aanpassingen van de site zijn best klein alleen het gehele plan is best wel groot. jessica heeft zelf voorgesteld om foto\'s te maken. Evie en Wouter zouden hiervoor gaan samen zitten met de klant om de foto\'s te gaan maken. Esmee zou dit dan fictief oppakken voor de foto\'s te maken. \r\n\r\n14-06-2022: Gisteren zou online oplevering plaatsvinden maar door uitval wifi niet doorgegaan. Mailtje is gestuurd voor nieuwe oplevering maar klant heeft nieuw voorstel gedaan.\r\n\r\n21-06-2022: De oplevering staat voor volgende week vrijdag gepland. Ze hebben een flink aantal mensen de omgeving laten testen. Hieruit kwamen geen verdere problemen, dus in orde. Voor de rest gaan ze nu alles afronden en dan verder met de documentatie af te ronden. \r\n\r\n08-07-2022: Maandag stond een eindoplevering kwamen een aantal fouten naar boven gaan ze nu oplossen. Vanmiddag oplevering (insert update).\r\n\r\n05-10-2022: Drie van de vier problemen zijn opgelost. Ze zijn nu beiden aan het kijken hoe ze dit verder gaan oplossen Het is een wordpress probleem. Dat is het enige wat nu nog moet gebeuren voor de oplevering van aankomende vrijdag. Ze gaan nog een keer samenzitten voor alle facturen en documentatie te ondertekenen. \r\n\r\n2022-10-11: Wacht op klant om eindgesprek in te plannen en oplevering te doen.\r\n\r\n18-10-2022: factuur is verstuurd samen met de handleiding. Voor de rest is ze bezig met dit volledig af te ronden. ', 'Software', 'ES-2022-14', 'Amber', '08/11/2022 11:25'),
(81, 'Corrosie Leeromgeving', 'Norah Blaauw', 'S. van der Vaart', 'Normaal', 'Cees-Jan Berman', '+31 6 383 752 42', 'bvandervaart@scalda.nl', 'Norah Blaauw, Oktay Aysay', 'Norah Blaauw en Daniel Willemkens', 'Bezig', 'Er is een forse hoeveelheid lesstof geschreven over het begrip corrosie. Het is bedoeling dat voor dit materiaal een aantrekkelijk online leeromgeving wordt gemaakt. Deze omgeving moet zowel functioneel zijn en aantrekkelijk. Hierdoor moet het op afstand leren worden gestimuleerd, ook moet het dienstbaar zijn aan het idee van het zelfstandig doorwerken van de stof.\r\n\r\n\r\n30-06-2022: is nu bezig met voorstel schrijven. klant komt binnenkort langs om dit te bekijken.\r\n\r\n07-07-2022: morgen word om 12:30 het project voorstel laten zien aan de klant.\r\n\r\n2022-10-11: Ze is bezig met haar documenten. Oktay komt deze sprint ook bij Norah op het project. Woensdag gesprek met klant om inhoud door te nemen. Hopelijk volgende week beginnen met realiseren.\r\n\r\n18-10-2022:  documentatie is af. Ze gaat morgen in gesprek met de klant, samenwerking met Oktay loopt goed. Ze zijn samen hieraan bezig. Na het gesprek van morgen gaan ze aan de feedback punten beginnen te werken. \r\n\r\n1-11-2022: Norah helpt Oktay met de ontwerpen een beetje te fine tunen zodat deze zo snel mogelijk. op kunnen leveren. Ze wilt de ontwerpen morgen af hebben. Ze heeft gaande weg ook nog wat aanpassingen gedaan in de documentatie. \r\n\r\n08-11-2022: Had gisteren klantgesprek, dit ging over ontwerpen. Deze zijn nu goedgekeurd. Wilt volgende week maandag beginnen aan realisatie.\r\n\r\n29-11-2022 : Vorige week donderdag heeft ze met de klant samengezeten. Hierin heeft ze met de klant nog een aantal dingen doorgenomen waar dat ze het domein neerzetten. Dit wordt deels binnen Scalda en deels binnen Corrosie zelf. Ze kunnen  nu verder met coderen. Ze heeft de klant verder geadviseerd over hoe ze nu verder kunnen gaan. \r\n\r\n7-12-2022: Het project loopt goed. ze is bezig met de realisatie voor hoe ver ze deze sprint daarmee is gekomen. Ze gaan vrijdag opleveren wat ze deze sprint hebben afgerond. Hierna gaat ze gewoon verder met de hoofdstukken. Het eerste hoofdstuk zou voor de kerst af zijn. Taken verdeling en communicatie tussen beide partijen loopt goed. ', 'Software', 'ES-2022-15', 'Dylan', '07/12/2022 11:19'),
(82, 'Stichting Escaldascholen', 'Teun Aardewerk', 'Maartje de Smit', 'Normaal', 'Wouter Mahu', '+31 6 312 892 01', 'maartjedesmit@escaldascholen.nl', 'Teun Aardewerk', 'Casper van Mook en Amber Middelkamp', 'Bezig', 'Hallo,\r\nWij (PR-groep Stichting Escaldascholen) zagen enkele weken geleden jullie oproep voor vormgevingsopdrachten voorbij komen. Wij werden direct enthousiast!\r\nWij hebben verschillende punten/ideeÃ«n die wij graag voor willen leggen:\r\n1. Ontwerp omslag rapporten. Momenteel hebben wij als Stichting Escaldascholen een vrij zakelijke omslag voor het rapport. Wij zouden graag een kindvriendelijkere voorkant voor de rapporten willen met daarbij ruimte voor de logo\'s van de scholen (die we er met een sticker op willen plakken) en ruimte voor de naam van het kind.\r\n2. In verband met de executieve functies en ontwikkeling van zelfstandigheid van kinderen, willen wij graag een agenda ontwerpen voor de groepen 5 t/m 8, waarbij het mogelijk is de eigen voorkant zelf samen te stellen (zodat de kinderen dus zelf de voorkant van hun agenda kunnen tekenen/ontwerpen). Hebben jullie hier ideeÃ«n over?\r\n3. Wij geven aan iedere nieuwe leerling een rugzak. Een welkomst gebaar vanuit de stichting. In deze tas zitten nu vaak papieren die ouders in moeten vullen (denk aan; Heeft uw kind allergieÃ«n?). Om het fijne gevoel van de rondleiding door de school vast te houden zouden wij graag een boekje/flyer laten ontwerpen, waardoor kinderen een gevoel van nagenieten krijgen (denk aan; foto\'s van de school in een boekje, een aftelkalender, 1e keer naar school informatie, etc.). Is het mogelijk zo\'n boekje samen te stellen?\r\n4. Tot slot zijn wij zoekende naar gebruiksvriendelijke Instagram en Facebook templates in de Escalda huisstijl, zodat we meer een doorgaande lijn en een herkenbaar beeld naar buiten kunnen brengen.\r\nWij horen graag of zulke dingen mogelijk zijn en of jullie ons hierbij kunnen helpen!! \r\nGroetjes, Maartje de Smit (uit het PR-team van Stichting Escaldascholen).\r\n\r\n\r\n30-06-2022: klant heeft niet veel tijd. Casper probeert dit nog wel online binnen schooltijd te regelen\r\n\r\n07-07-2022: initiatie staat gepland voor volgende week woensdag.\r\n\r\n07-09-2022: project is klaar om te starten er moet alleen nog project voorstel gemaakt worden.\r\n\r\n\r\n05-10-2022: Niet heel veel vooruitgang geboekt. De klant heeft wegens prive redenen niet veel tijd gehad, om te mailen. Hij is door de notules gelopen en heeft hieruit nog bruikbare informatie voor het project te starten. \r\n\r\n2022-10-11: Is begonnen.\r\n\r\n18-10-2022: klanten contact is vreselijk. Het loopt heel moeizaam. hij is nu in de conceptfase, volgende pitch staat voor donderdag. \r\n\r\n08-11-2022: Vanwege wat slechtere communicatie is er even een nieuw gesprek geweest om concrete afspraken te maken over de gang van zaken.\r\n\r\n22-11-2022: Gaat wat minder: Is een aantal dingen kwijt door problemen met laptop. Klant is op de hoogte gebracht. Loopt dus wat achter. Woensdag 30 november staat de meeting gepland.\r\n\r\n7-12-2022: hij zit in zijn ontwerp fase, de klant had nog wat feedback op zijn pitch. Hierop heeft hij dit aangepast en nog wat feedback ontvangen en aangepast. Hij gaat voor vrijdag zijn pitch inplannen, via een mail. ', 'Media', 'EM-2022-15', 'Dylan', '07/12/2022 11:22'),
(83, 'Huisstijl ICT beheer Terneuzen', 'Roxanne van Hulle', 'Levi van den Bussche', 'Normaal', 'Wouter Mahu', '+31 6 222 850 13', 'lvandenbussche@scalda.nl', 'Roxanne van Hulle', 'Lana de Rijk en Oktay Aysay', 'Bezig', 'Graag willen wij een nieuwe huisstijl voor de opleiding N2/3 in Terneuzen\r\n\r\n30-06-2022: project voorstel is af en moet nu alleen nog ondertekent worden door de coach en de klant.\r\n\r\n05-10-2022: ze heeft akkoord gehad op de offerte van Levi. Dit duurde erg lang. Het contact wat ze heeft loopt erg moeizaam. Ze is erg bang dat ze de deadline van begin november niet gaat halen. \r\n\r\n18-10-2022:  aankomende vrijdag pitch voor kleine tussenoplevering.\r\nDe klant, Levi, doet er erg lang over om snel te reageren. Hierop heeft ze de klant wel al gewezen. ', 'Media', 'EM-2022-16', 'Tristan', '13/11/2022 00:27'),
(84, 'Schaats/ Leisurehal Zeeland', 'Kylian de kwant', 'Adriaan Provoost', 'Normaal', 'Wouter Mahu', '+31 6 124 539 10', 'aprovoost@zeelandnet.nl', 'Kylian de kwant', 'Manon Fermont en Tristan Verschueren', 'Bezig', 'Beeldimpressie over dit project, gericht op samenhang tussen sport- inwoners-onderwijs - energieopwekking en toerisme.\r\nBeelden van ons mooie Zeeland gecombineerd met beelden betreffende de toepassingen die in dit project mogelijk gemaakt worden.\r\nProject bestaat uit 400 m schaatsbaan en 30 x60 ijshockey/shorttrackbaan, indoor golfsurfbassin, boulderhal, fitnessruimte, icetubbingbaan,\r\nkleedkamers en horeca. Na maart tot aan oktober krijgt hal een andere functie, gericht op beleving sport en spel voor jongeren boven 12 jaar en allerlei zomerevenementen.\r\n\r\n\r\naprovoost@zeelandnet.nl\r\n0612453910\r\n\r\n30-06-2022: komende dinsdag initiatie\r\n\r\n07-07-2022: initiatie gehad projectvoorstel moet nog gemaakt worden.\r\n\r\n07-09: project kan gestart worden, projectvoorstel was niet af. het gedeelte dat al gemaakt was moet overgegeven worden van Tristan naar de persoon die het project oppakt\r\n\r\nVrijdag conceptpitch gehad. Klant heeft script opgestuurd maar is nogal een groot script met wollige teksten.\r\n\r\n29-11-2022 : Het interview is af wat een aantal weken geleden is opgenomen. Hij gaat daarna de tekst animeren voor in het filmpje. Hij gaat hierna de klant mailen over de status van het project. Hij moet nu nog even kijken welke sprints en betalingen hoe deze verder worden geregeld. ', 'Media', 'EM-2022-17', 'Dylan', '29/11/2022 11:48'),
(85, 'Social media template', 'Dylan Bouwhuizen', 'Evie Jongbloeds', 'Normaal', 'Wouter Mahu', '-', '-', 'Dylan Bouwhuizen', 'Dylan Bouwhuizen', 'Afgerond', 'Ik moet een huisstijl, en een lay-out ontwerpen voor op social media. Dit moet binnen de al bestaande huisstijl. Voornaamlijk voor Instagram, en facebook. Evie heeft deze gemaakt samen met hun website. \r\n\r\n10-5-2022: Loopt soepel, heeft met de klant contact gehad. Heeft feedback gehad, stuurt dit z.s.m. door naar de klant dan is dit opgeleverd.\r\n\r\n17-05-2022: Klant was tevreden, met het opleveren. \r\n\r\n14-06-2022: Vorige week oplevering gehad, klant was deels tevreden met wat feedback puntjes. Nieuwe oplevering staat vast voor donderdag\r\n\r\n21-06-2022: oplevering gehad. ', 'Media', 'EM-2022-17', 'Amber', '08/11/2022 10:03'),
(86, 'RenÃ© Coldenhoff', 'Amber Middelkamp', 'Rene Coldenhoff', 'Normaal', 'Wouter Mahu', '+31 6 104 053 92', 'rcoldenhoff@maatvoeren.nl', 'Amber Middelkamp', 'Ruben Struijlaart en Katja Willemse', 'Bezig', 'Vernieuwen van de bestaande huisstijl en logo\r\n\r\n\r\n21-06-2022: contact gehad, gaat binnenkort een meeting inplannen zodat ze aan het project kan beginnen. In dat gesprek gaat ze meer informatie ophalen en de wensen en eisen doornemen.\r\n\r\n28-06-2022: Onderzoek is gedaan. Concepten zijn af. Ze gaat zo snel mogelijk pitches inplannen voor oefenen en af te ronden.\r\n\r\n05-10-2022: Ze is de offerte aan het afronden, zodat de afspraken vast staan. ze gaat de klant mailen voor een concept pitch in te plannen. \r\n\r\n11-10-2022: Klant heeft deze week geen tijd meer voor een pitch.\r\n\r\n18-10-2022: Ze heeft net met wouter gesproken, dat deze week niet haalbaar is door hindernis vanaf de klant zijn kant. het project wordt hierdoor naar achter geschoven voor na de herfstvakantie\r\n\r\n08-11-2022: De conceptpitch was ingepland alleen moest dit verplaatst worden vanwege een ongeluk met Amber zelf. Zijn nu een nieuwe datum aan het plannen voor de pitch.\r\n\r\n14-11-2022: Conceptpitch is gedaan, en er is een concept gekozen. Ze gaat nu verder naar de ontwerpfase.\r\n\r\n29-11-2022 : Ze zit nu in de ontwerpfase, ze loopt hierin een beetje vast. Haar creativiteit laat haar een beetje in de steek. De volgende pitch moet ze nog even opnieuw inplannen. \r\n\r\n7-12-2022: Ze heeft een aantal nieuwe ideeÃ«n uitgewerkt. Die heeft ze bijna afgerond. Ze heeft de klant een mail gestuurd voor een volgende pitch. Ze kan in de tussentijd van afwachten verder aan de ontwerpen werken.', 'Media', 'EM-2022-18', 'Dylan', '07/12/2022 11:27'),
(87, 'Herkansingen Digitaliseren ', '-', 'Josefien Almekinders', 'Normaal', '-', '-', '-', '-', 'colin en yannick', 'Gestopt', 'Mijn naam is Josefien en ik ben docent bij de opleiding Logistiek.\r\nBinnen onze opleiding werken we met 4 perioden van 10 weken wat afgesloten wordt met toets week.\r\nHalverwege de periode is er een herkansing mogelijkheid voor max. 2 vakken.\r\nDit is dan ook de reden dat ik u mail.\r\nWe zouden de aanvraag van herkansingen graag digitaliseren.\r\nZo voorkomen we dat studenten meer dan 2 herkansingen doen en de docenten weten hoeveel studenten welk vak willen herkansen.\r\n\r\ntel: 0648519298\r\nemail: jalmekinders@scalda.nl\r\n\r\n30-06-2022: net initiatie gehad, ging goed. is nu project voorstel aan het schrijven.\r\n\r\n07-07-2022: projectvoorstel is opgestuurd wacht nu op reactie', 'Software', 'ES-2022-19', 'Ruben', '12/09/2022 13:52'),
(88, 'Werken in de binnenvaart', 'Lana de Rijk', 'Evie Jongbloets', 'Normaal', 'Wouter Mahu', '+31 6 394 305 80', 'info@in1online.nl', 'Lana de Rijk', 'Lana de Rijk', 'On Hold', 'Voor Vario Shipping wil ik graag een filmpje wat werkzaamheden, functies en het mooie van werken in de binnenvaart reflecteert. Het filmpje is bedoeld om sollicitanten te trekken naar de website.\r\n\r\n17-05-2022 Vrijdag is het initatie gesprek gepland.\r\n\r\n31-05-2022 offerte is verstuurd. Morgen wordt er op locatie gekeken voor verschillende onderwerpen in beeld gebracht. \r\n\r\n07-06-2022: Vandaag concept gepitcht, in planning geen rekening gehouden met vrije dagen en evenement vrijdag.\r\n\r\n21-06-2022: Morgen staat een oefen pitch ingeplant, Wegens overlijden in de familie van de klant is er slecht contact. Ze gaat contact opnemen met soortgelijke mensen binnen het bedrijf en wilt zo de draad verder oppakken\r\n\r\n28-06-2022: Contact gelegd. Helaas geen concreet antwoord gekregen van de klant. Maar moeilijk te bereiken ivm vorig incident. \r\nContact met Evie leggen zodat er meer vooruitgang komt in het process en in het project.\r\n\r\n08-07-2022: Gaat nieuwe mail sturen naar klant dat ze na de vakantie verder gaan. IVM ziekte Lana heeft ze niet veel kunnen doen.\r\n\r\n2022-10-11: Over 2 weken beginnen met filmen verder geen update.\r\n\r\n18-10-2022: woensdag gaan ze filmen op de boot. nu is er wat gedoe met mensen die mee mogen op die boot. Lana vind het project moeizaam lopen, door gebrek aan informatie. \r\n\r\n7-12-2022: Ze moet nog een keer gaan filmen. De klant gaat nog een keer contacteren, dit zal heel random gebeuren dus waarschijnlijk niet op voorhand goed aan worden gegeven. ', 'Media', 'EM-2022-20', 'Dylan', '07/12/2022 11:13'),
(89, 'Website 5th Dimension Gallery', '-', 'Thomas Goossens', 'Normaal', '-', '-', '-', '-', 'Dylan en damian', 'Gestopt', 'Graag wil ik een website laten bouwen die gebruiksvriendelijk is en als doel heeft: -producten verkopen\r\n-informatie over werkwijze geven\r\n-uitgebreid contactformulier\r\n- bereikbaarheid vergroten\r\n\r\nTel: 0610166134\r\nEmail: parabolatattoos@hotmail.com\r\n\r\n30-06-2022: mailtje gestuurd voor volgende week woensdag. klant heeft nog niet geaccepteerd.\r\n\r\n07-07-2022: initiatie staat nog niet ingepland, Dylan is nu aan het kijken of er nog coaches beschikbaar zijn in de bufferweek.', 'Software', 'ES-2022-21', 'Ruben', '07/09/2022 12:14'),
(90, 'Internationalisering kaartjes', 'Teun Aardewerk', '?', 'Normaal', 'Wouter Mahu', 'Teun Aardewerk', 'Teun Aardewerk', 'Teun Aardewerk, Timo Fieret', 'Teun Aardewerk', 'Afgerond', 'Het is de bedoeling dat er 18 kaartjes worden ontworpen voor een meeting van internationalisering op 5 juli. De deadline is dus 4 juli.\r\n\r\n15-06-2022: We hebben de initiatie al gehad en de conceptfase wordt op dinsdag 21 juni afgerond. Ik heb ook de ondertekende offerte bijgevoegd.\r\n\r\n21-06-2022: Vandaag concept pitch gehad, akkoord gekregen op de concepten van de klant. \r\n\r\n28-06-2022: Vanochtend ontwerppitch gehad, morgen oefenrealisatie pitch en overmorgen (donderdag) realisatie pitch. Weinig tot geen feedback omdat het allemaal soepel loopt. \r\n\r\n08-07-2022: Project is afgerond.', 'Media', 'EM-2022-22', 'Ruben', '12/09/2022 13:40'),
(91, 'Kortech', 'JoÃ«l Schout', 'Cees-jan Berman', 'Normaal', 'Cees-Jan Berman', 'JoÃ«l Schout', 'JoÃ«l Schout', 'JoÃ«l Schout', 'JoÃ«l Schout', 'Gestopt', 'Kortech is een bedrijf gespecialiseerd in tuin en park machines. Ze zijn gevestigd in Westkapelle op Walcheren. Ze verkopen en verhuren diverse machines onder andere grasmaaiers, zitmaaiers, heggenscharen, bosmaaiers, kettingzagen etc.  \r\nOok voeren ze reparaties uit en eenvoudige laswerkzaamheden. Ze repareren tuin- en parkmachine en elektrische handgereedschappen.  \r\nKortecht levert onderdelen van landbouwmachines en zorgt voor de juiste brandstof van uw machines.\r\n\r\n21-06-2022: Sprintofferte is goedgekeurd voor de rest is er niet veel feedback. Hij is nu bezig met functioneel ontwerp. Daarna wil hij aan technisch ontwerp verder.\r\n\r\n08-07-2022: Project is aan het afronden. Gaat Cees-Jan laten testen en maakt een implementatieplan.\r\n\r\n26-09-2022: Joel is klaar met examen. project hoeft niet meer gebruikt te worden. dus hij word stop gezet.', 'Software', 'ES-2022-23', 'Ruben', '26/09/2022 09:17'),
(93, 'Logo Huis van de Toekomst', 'Timo Fieret', 'Steef de Gruiter', 'Normaal', 'Wouter Mahu', '+31 6 219 571 43', 'gruist@scalda.nl', 'Timo Fieret', 'Timo Fieret', 'Afgerond', 'Voor het Scalda Project Huis van de Toekomst zouden wij graag een logo en/of (compacte) huisstijl laten ontwikkelen.\r\n\r\n18-10-2022: Hij is druk bezig met de ontwerpfase voor zijn project, hij is nu aan het ontwerpen. De ontwerppitch staat waarschijnlijk voor donderdag. Daarna gaat hij realisatie pitch houden. ', 'Media', 'EM-2022-24', 'Dylan', '29/11/2022 11:41'),
(94, 'Webshop De Platenbaas', 'Ruben Struijlaart', 'Wouter Mahu', 'Normaal', 'Vincent Brunings', '+31 6 416 779 20', 'info@deplatenbaas.com', 'Mathieu Heyindrickx', 'Ruben Struijlaart', 'Bezig', 'Hallo,\r\nik heb dringend behoefte aan een werkende webshop. Enkele jaren geleden is mijn huidige website gemaakt door studenten SD in Vlissingen, maar is inmiddels niet meer werkzaam door allerhande fouten die niet opgelost (kunnen) worden.\r\nGraag wil ik:\r\n- een eenvoudige/overzichtelijk webshop voor vinyl, met enkele categorieÃ«n (zie huidige site http://www.deplatenbaas.com). Hoeft geen home-pagina te hebben, mag rechtstreeks shop zijn\r\n- voorraadbeheer; producten moeten kunnen worden toegevoegd vanuit een specifiek csv-bestand (voorbeeldbestand kan worden aangeleverd), en vervolgens in de website (admin gedeelte) eventueel kunnen worden aangepast. Liefst ook mogelijkheid om gehele voorraad in 1x te kunnen overschrijven\r\n- belangrijk: afbeeldingen moeten automatisch bij productnummer worden opgezocht (gebeurde eerst volgens mij via eBay maar werkt niet meer). Eventueel koppeling met website van mijn huidige leverancier mogelijk. Daarnaast moet ik deze afbeeldingen ook manueel kunnen wijzigen\r\n- wereldwijd verzendkosten, nadruk op NL en Europa (deze kosten moeten door mij kunnen worden aangepast bij prijsstijgingen). Ophalen in winkel is ook mogelijk > dan geen verzendkosten\r\n- betaalmogelijkheden Paypal, iDeal, ...\r\n- bij plaatsen order: ik wil notificatie ontvangen, de factuur moet automatisch verstuurd worden en ik moet deze indien nodig kunnen passen (kan nu niet)\r\n- mogelijkheid tot een kortingscode invullen, die ik zelf kan aanmaken (specifiek bedrag en %)\r\nMisschien al teveel details, maar dit zijn wel de belangrijkste punten.\r\nIk kijk uit naar jullie reactie!\r\nmvg\r\nWouter Mahu - De Platenbaas Vlissingen\r\n\r\n08-11-2022\r\nZit in sprint 2, de documentatie is volledig gemaakt, maar hier is nog geen akkoord op. Heeft geen akkoord gekregen, maar gaat wel door naar de realisatiefase. Blijkt verkeerd mailcontact te zijn met de klant, hier word dan wat meer aandacht aan besteed\r\n\r\n14-11-2022: Volgende weer userstories af en landing page moet af.\r\n\r\n29-11-2022 : Mathieu neemt dit project verder over als examen project. initiatie gesprek is al geweest, dus hij gaat dit project nu verder door laten  lopen. \r\n\r\n7-12-2022: vorige week initatie gesprek gehad, Vincent moet eerst zijn project goedkeuren. Voor de rest moet hij gewoon verder werken. ', 'Software', 'ES-2022-25', 'Dylan', '07/12/2022 11:57'),
(95, 'Platenbaas poster', 'Katja Willemse', 'Wouter Mahu', 'Normaal', 'Wouter Mahu', '+31 6 485 211 94', 'wmahu@scalda.nl', 'Katja Willemse', 'Katja Willemse', 'Bezig', 'Voor een vinylbeurs in Vlissingen -datum nog niet bekend- moet een aankondigingsposter gemaakt worden.\r\n\r\n05-10-2022: concept pitch gehad hierop akkoord gehad. De ontwerp fase aan begonnen. De pitch staat ingeplant. \r\n\r\n2022-10-11: Feedback verwerken en gaat moment inplannen voor pitch\r\n\r\n18-10-2022:  ze moet nu aan haar realisatie pitch beginnen met de klant. Hieraan was ze wel al begonnen. \r\n\r\n1-11-2022: ze heeft feedback gehad voor de vakantie. De pitch staat voor vandaag. ', 'Media', 'EM-2022-26', 'Amber', '04/11/2022 13:56'),
(96, 'Huisstijl GPC Vlissingen', 'Nathan Stoffels', 'Vincent Brunings', 'Normaal', 'Vincent Brunings', '+31 6 485 195 43', 'brunvi@scalda.nl', 'Nathan Stoffels', '-', 'Bezig', 'Als voetbalvereniging willen we een professionelere uitstraling hebben. Er is op dit moment geen huisstijl en dat zorgt er voor dat verschillende mensen hun eigen creativiteit er op los laten. We willen alleen dat er meer een vaste lijn in komt. Kunnen jullie meedenken in hoe wij als vereniging een meer professionele uitstraling kunnen krijgen?\r\n\r\n05-10-2022: hij is aan het wachten op een initatie gesprek, hiervoor is hij al wat informatie aan het verzamelen. voor voor te bereiden op dit gesprek.\r\n\r\n11-10-2022: Donderdag staat een initiatiegesprek op de planning.\r\n', 'Media', 'EM-2022-26', 'Amber', '04/11/2022 14:20'),
(97, 'Parfumerie van Biemen', 'Yannick Elias', 'Reinier', 'Normaal', 'Cees-Jan Berman', '-', 'reinier@parfumerievanbiemen.nl', 'Yannick Elias, Justin', 'Yannick Elias', 'Bezig', '18-10-2022: vorige week initiatie mail gestuurd. een reactie gehad met een aantal tijdstippen. Nu is het afwachten op antwoord van een van de coaches. Cees-Jan is hiervoor niet beschikbaar dus wordt een andere coach. \r\n\r\nvoor www.Parfumerievanbiemen.nl willen we graag een nieuwe frisse website.\r\n\r\n08-11-2022: Is bezig met ontwerpen. Heeft gisterenavond een herinnering gestuurd voor antwoord op mail zodat hij verder kan.\r\n\r\n22-11-2022: Is nu bezig met ontwerpen. wil deze week een gesprek over de templates. Verder loopt het project volgens planning.\r\n\r\n29-11-2022 : Gisteren een oplevering van de ontwerpen gehad, deze zijn goedgekeurd. Het contact verloopt erg stroef hij zit er dicht op. \r\n\r\n7-12-2022: Hij is bezig met documentatie, hij is bezig met de ontwerpen. ', 'Software', 'ES-2020-??', 'Justin1', '07/12/2022 13:08'),
(99, 'Reserveringsysteem lokalen (PMS)', 'Jessica Asaad', 'Tristan Verschueren', 'Normaal', 'Cees-Jan Berman', '+31 6 407 489 62', '227967@student.scalda.nl', '-', 'Jessica Asaad', 'Bezig', 'Er moeten reservering systemen komen of 1 reserveringssysteem voor E.0.08 - Vergaderruimte, E.0.14 - Workshopruimte, E.0.15 -Klantendomein, E.0.16 - Gerhard H. Kamer. Dit word nu nog op papier gedaan maar dit zouden wij graag willen digitaliseren.\r\n\r\nHet systeem wordt gelinkt aan het al bestaande Project Management Systeem. en moet dus ook hetzelfde uiterlijk krijgen als de PMS en de Templates website.\r\n\r\n22-11-2022: Zijn begonnen aan realisatie. Ontwerpen zijn goedgekeurd door klant.\r\n\r\n7-12-2022: Ze hebben met de klant initatie gehad, ze hebben ook wireframes gemaakt en goegdekeurt door de klant. Sam is een basis formulier aan het maken. Ze gaan aan de klant vragen of de klant maandag of dinsdag samen te zitten zodat ze de voortgang kunnen bespreken.\r\n', 'Software', 'IS-2022-28', 'Dylan', '07/12/2022 11:44'),
(100, 'LiveCare', 'Mats Segers', 'Lieneke van Veelen', 'Normaal', 'Wouter Mahu', '06 231 404 59', 'Lrvanveelen@gmail.com', 'Mats Segers ', '-', 'Bezig', 'ik ben op zoek naar een mooi logo (en in overleg daarna eventueel uitbreiding voor huisstijl/visitekaartjes/website) voor mijn startende bedrijf LiveCare in de zorg. (PS niet altijd makkelijk telefonisch bereikbaar, liefst even per email een tijdstip voor telefonisch contact afspreken)', 'Media', 'EM-2022-29', 'Amber', '04/11/2022 13:46'),
(101, 'Logo Yogapraktijk', 'Lana de Rijk', 'Lo van Deursen-Brouwer', 'Normaal', 'Wouter Mahu', '+31 6 280 720 22', 'loana.e.brouwer@gmail.com', 'Lana de Rijk', 'Lana de Rijk', 'Bezig', 'Goedendag, Voor mijn yogapraktijk zou ik graag een bijpassend logo willen wat de juiste klanten aantrekt. Mijn zoon Timo Fieret vertelde mij dat ik hiervoor bij jullie aan het juiste adres ben. Ik heb wel wat ideeÃ«n, maar niets concreets en ik heb geen idee wat mogelijk is. Alvast bedankt voor de hulp! Met vriendelijke groet, Lo van Deursen\r\n\r\n18-10-2022: nog geen initiatie kunnen doen voor dit project, er is wel al een mailtje verstuurd naar de klant. \r\n\r\n7-12-2022: Vrijdag moet ze nog een meeting inplannen voor haar concept pitch. Ze loopt niet gelijk met de sprint verder. De klant heeft dan tijd. ', 'Media', 'EM-2022-30', 'Dylan', '07/12/2022 11:13'),
(102, 'Intervance', 'Menno de Pooter', 'Stefan Oreel', 'Normaal', 'Wouter Mahu', '+31 6 845 472 11', '228530@Student.scalda.nl', 'Menno de Poorter', '-', 'Afgerond', 'Wij zijn een nieuw opkomend leerbedrijf Intervance (Scalda Vlissingen) en wij zouden graag voor ons bedrijf een nieuwe huisstijl willen. (voor meer uitleg over ons bedrijf kan je terecht bij Tristan die weet hier alles vanaf)\r\n\r\n08-11-2022: Donderdag staat ontwerpfase oplevering gepland. Had eerst nog kleine vertraging door problemen met doelgroep, maar dit is als het goed is nu opgelost. \r\n', 'Media', 'EM-2022-31', 'Dylan', '29/11/2022 11:29'),
(103, 'Ontwerpen Sportshirts', 'Dylan Bouwhuizen', 'Steef van de Gruiter', 'Normaal', 'Wouter Mahu', '+31 6 219 571 43', 'Svandegruiter@Scalda.Nl', 'Dylan Bouwhuizen', 'Dylan Bouwhuizen', 'Bezig', 'Wij als team ict en media van het Scalda gaan individueel en in estafette de marathon van Zeeuws Vlaanderen lopen. Dit willen wij doen in sportshirts die vormgegeven zijn door jullie. voorkant is het ideetje IVS logo + Scalda. op de achterzijde logo\'s van stage bedrijven en partners van ons. Deze zal ik aanleveren. Ik heb iemand gevonden die de shirts kan en wil drukken en zij werkt met circut apparatuur en wil hierin vast een workshop in geven enz. Ook kan zijn helpen in de mogelijkheden. Kwa shirts denk ik aan het merk JAKO maar hierin mag je ook adviseren. Ik denk een leuke en creatieve opdracht waarin wij overal voor open staan en het gekozen ontwerp gaan dragen tijdens de marathon :) Https://Www.Jakoteamkleding.Nl/Running/Hardloop-Shirts/T-Shirt-Run-2-0/', 'Media', 'EM-2022-32', 'Amber', '08/11/2022 10:04'),
(104, 'Memory kaartjes ', 'Dylan Bouwhuizen', 'Steef van de Gruiter', 'Normaal', 'Wouter Mahu', '+31 6 219 571 43', 'Svandegruiter@Scalda.Nl', 'Dylan Bouwhuizen', 'Dylan Bouwhuizen', 'Bezig', 'Samen met mijn studenten wil ik kabel connectoren gaan leren. Ik heb de afgelopen weken kabels verzameld en de connectoren hieraf geknipt. Deze zitten in een soort grabbelton. Nu krijgen zij volgende sprint als opdracht alles over een van de kabels op te zoeken en een aantal feitjes uit te werken voor op een soort spel kaart. Hiervoor ben ik opzoek naar een sjabloon en vormgeving. Dit heeft wel prioriteit en zou ik graag aan het einde van sprint twee in gebruik nemen. Ik zou graag foto\'s mailen van een voorbeeld en de kabels ter inspiratie.\r\n\r\n11-10-2022: Initiatie goed verlopen heeft vervolgstappen gedeeld met de klant. Wil morgen oefenpitch geven. \r\n\r\n18-10-2022: Loopt op schema concept fase is afgerond.\r\n\r\n08-11-2022: Loopt iets achter op schema, loopt tegen wat kleinere dingetjes aan. Zoals fonts downloaden enz. Mist nog wat informatie voor op de kaartjes, voor mock-up. Als het goed is, is de achterstand makkelijk in te halen. ', 'Media', 'EM-2022-32', 'Tristan', '22/11/2022 21:43'),
(108, 'Beeldmateriaal e-learning', '-', 'Vincent Brunings', 'Normaal', 'Vincent Brunings', '0648519543', 'brunvi@scalda.nl', '-', '-', 'Initiatie', 'Type project: Het is een combinatie van Beeld en Vormgeving Op dit moment zijn wij bezig met het ontwikkelen van een e-learning over scrum. De teksten hiervoor zijn we zelf aan het schrijven, maar we willen de tekst ondersteunen met allerlei beeldmateriaal. Dat kunnen foto\'s zijn, infographics en filmpjes. De filmpjes zouden dan een aanvulling op de tekst zijn, maar ook in plaats van een stuk tekst.', 'Media', 'IM-2022-33', 'Tristan', '22/11/2022 21:48'),
(110, 'Duivenarts', '-', 'Kevin Schuit', 'Normaal', 'Cees-Jan Berman', '+31640217589', 'Info@Kevinschuit.com', '-', '-', 'Initiatie', 'Duivenarts is een bestaande webshop binnen Wordpress. Op dit moment is de webshop omtrent php verouderd en is het thema niet stabiel meer om overgezet te worden in php 8.x. Om deze reden de keuze om hier een nieuw thema voor te laten ontwikkelen. De enige eisen zijn: - Webshop items en data moet intact blijven. - Systeem moet op klant niveau behaarbaar blijven, klant moet hier zelf aanpassingen in kunnen doen en dit moet geen technische kennis bevatten.', 'Software', 'ES-2022-35', 'Amber', '04/11/2022 14:16'),
(111, 'Sunshine shop (examen?)', '-', 'Kevin Schuit', 'Normaal', 'Cees-Jan Berman', '+31640217589', 'Info@Kevinschuit.com', '-', 'Nick Kroezen, Ibraim Amet', 'Initiatie', 'Een webshop om kleine productjes in te verkopen, deze kan op latere termijn uitgebreid worden om meer producten in kwijt te kunnen. Op dit moment is er enkel een logo & als inspiratie bron is de volgende site gebruikt: Https://Positivityshop.Nl Site moet beheerbaar zijn op klant niveau en hier moet niet al te veel technische kennis voor nodig zijn. Deadline: Liefst voor de kerst, indien dit niet mogelijk is hoor ik graag wat er wel mogelijk is.', 'Software', 'ES-2022-36', 'Vbrunings', '17/11/2022 10:19'),
(113, 'Wijkcentrum de Burgerij', '-', 'Cindy Kooij', 'Normaal', 'Cees-Jan Berman', '-', 'Cindy.Kooij.bpuaaeaara@Users.roc.nl', '-', '-', 'Initiatie', 'Wijkcentrum de Burgerij is een actief centrum in de wijk Paauwenburg (Middelburg). Wij zouden het ontzettend fijn vinden wanneer we voor onze website zouden kunnen samenwerken met een Scalda student Grafisch Vormgeven / media. Het wijkcentrum wordt volledig gedraaid op vrijwilligers. De website is opgebouwd met Joomla en zou wat opgefrist moeten worden naar deze tijd. Wat zijn de mogelijkheden omtrent deze vraag? Het gaat om de layout van de website Www.wijkcentrumdeburgerij.nl', 'Media', 'EM-2022-37', 'Tristan', '17/11/2022 10:10'),
(114, 'Nieuwe website Vitrite Middelburg', '-', 'Marcel de Visser', 'Normaal', 'Cees-Jan Berman', '+31620675131', 'marcel.de.visser@vitrite.com', '-', '-', 'Initiatie', 'Als bedrijf Vitrite Middelburg willen we onze website opnieuw vorm geven. Het idee is om dat in projectvorm samen met een aantal studenten van het Scalda te doen die een opleiding doen wat hier een raakvlak mee heeft. Marcel de Visser - IT Manager Vitrite Middelburg', 'Software', 'ES-2022-38', '-', '-'),
(115, 'Wordpress Website (examen?)', '-', 'Joke Feitsma', 'Normaal', 'Cees-Jan Berman', '+31 6 144 737 23', 'info@jokewf.nl', '-', '-', 'Initiatie', 'Beste medewerker, Voor mijn werk als beeldend kunstenaar is mijn website mijn visitekaartje. Helaas is de site die ik nu heb, www.jokewf.Nl heel lastig om te onderhouden omdat er verschillende systemen in zitten. Daarom ben ik op zoek naar een student mediavormgeving die de site wil aanpassen naar wordpress. Uiteraard tegen een vergoeding. Is er wellicht onder uw studenten iemand die dat een leuke klus vindt? Dan zou ik daar graag mee in contact komen. Vriendelijke groet, Joke Feitsma', 'Software', 'ES-2022-39', 'Vbrunings', '17/11/2022 10:20'),
(116, 'Duitensysteem (PMS)', 'Casper van Mook', 'Wouter Mahu', 'Normaal', 'Cees-Jan Berman', '+31 6 416 779 20', 'wmahu@scalda.nl', 'Casper van Mook', 'Casper van Mook & Ibraim Amet', 'Bezig', 'Een systeem ontwikkelen voor studenten die tijd buiten school maken voor bijvoorbeeld het bijwonen van evenementen en/of projecttijd buiten de schooltijden.\r\n\r\nStudenten krijgen dan de tijd die ze buiten school hebben gemaakt terug in de vorm van punten die ze kunnen opsparen en inzetten voor vrije tijd / een vrije dag.\r\n\r\nHet systeem wordt gelinkt aan het al bestaande Project Management Systeem. en moet dus ook hetzelfde uiterlijk krijgen als de PMS en de Templates website.\r\n\r\n29-11-2022 : Casper heeft een initatie gesprek gehad en is nu bezig aan het project voorstel. Hierna gaat hij verder aan zijn ontwerp werken. \r\n\r\n7-12-2022: bezig met documentatie.', 'Software', 'ES-2022-40', 'Dylan', '07/12/2022 11:48'),
(117, 'Huisstijl/Logo - D4A', 'Menno de Poorter', 'Ed Peerbolten', 'Hoog', 'Wouter Mahu ', '+31 6 510 816 88', 'tverschueren2@student.scalda.nl', 'Menno de Poorter ', 'Menno de Poorter & Yoran de Blaey', 'Bezig', 'Vraag naar moderniseren van huisstijl en logo voor \'de 4 Ambachten\'. Kleuren staan al vast: \r\nKleuren zijn(HEX-codes): -> Zeeuws DNA: Klei bruin en gras groen\r\n#7C241  --> PMS63C \r\n#6D6152 \r\n\r\n29-11-2022 : Gisteren initiatie gesprek gehad, offerte is klaar en al verstuurd richting de klant. \r\n\r\n', 'Media', 'EM-2022-41', 'Woutermahu', '07/12/2022 14:19'),
(118, 'Reclame Video\'s - D4A ', '-', 'Ed Peerbolten', 'Normaal', 'Wouter Mahu', '+31 6 510 816 88', 'tverschueren2@student.scalda.nl', '-', '-', 'Initiatie', 'Maken van nieuwe reclame video\'s voor de 4 Ambachten.\r\n', 'Media', 'EM-2022-42', 'Amber', '17/11/2022 11:33'),
(119, 'Re-design website - D4A ', '-', 'Ed Peerbolten', 'Normaal', 'Wouter Mahu', '+31 6 510 816 88', 'tverschueren2@student.scalda.nl', '-', '-', 'Initiatie', 'Re-designen website van de 4 Ambachten ', 'Media', 'EM-2022-43', 'Amber', '17/11/2022 11:35'),
(120, 'Kaart re-designen - D4A', '-', 'Ed Peerbolte', 'Normaal', 'Wouter Mahu', '+31 6 510 816 88', 'tverschueren2@student.scalda.nl', '-', '-', 'Initiatie', 'Re-designen van plattegrond/kaart.', 'Media', 'EM-2022-44', 'Woutermahu', '23/11/2022 15:21'),
(121, 'App de Vier Ambachten', '-', 'Ed Peerbolte', 'Normaal', 'Cees-Jan Berman', '+31 6 510 816 88', 'tverschueren2@student.scalda.nl', '-', '-', 'Initiatie', 'Maken van app voor de 4 Ambachten.\r\n', 'Software', 'ES-2022-45', 'Tristan', '30/11/2022 11:23'),
(122, 'Fiets/Wandeltocht - D4A', '-', 'Ed Peerbolte', 'Normaal', 'Cees-Jan Berman', '+31 6 510 816 88', 'tverschueren2@student.scalda.nl', '-', '-', 'Initiatie', 'Software waarbij je kunt zien waar je bent en in geval dat, informatie over een bepaald punt/locatie. Dit voor een Fiets/Wandeltocht.', 'Software', 'ES-2022-46', 'Woutermahu', '23/11/2022 15:20'),
(123, 'Intro/ Outro (animatie) - D4A', '-', 'Ed Peerbolte', 'Normaal', 'Wouter Mahu', '+31 6 510 816 88', 'tverschueren2@student.scalda.nl', '-', '-', 'Initiatie', 'Maken van intro/outro voor (reclame)video\'s voor de 4 Ambachten.', 'Media', 'EM-2022-47', 'Woutermahu', '23/11/2022 15:20');
INSERT INTO `project` (`id`, `projectnaam`, `projectleider`, `klant`, `prio`, `projectcoach`, `telefoonnummer`, `emailklant`, `projectleden`, `initiatieleider`, `project_status`, `opmerkingen`, `opleiding`, `administratienummer`, `bewerkt_door`, `bewerkt_datum`) VALUES
(124, 'Sponsormeter (examen)', 'Ruben Struijlaart', 'Steef de Gruiter', 'Normaal', 'Cees-Jan Berman', '+31 6 219 571 43', 'gruist@scalda.nl', 'Ruben Struijlaart', 'Ruben Struijlaart', 'Bezig', 'In het voorjaar doen een aantal docenten mee aan een marathon. Jullie hebben al mee mogen denken over de shirts die gedragen gaan worden t.b.v. de sponsoring. We verwachten dat er meer geld ingezameld gaat worden dan nodig en willen het te veel aan sponsoring schenken aan een goed doel. Het ingezamelde bedrag willen we op een leuke manier op een website delen. Denk aan en meter die zich steeds verder vult (maar dan creatiever).\r\n\r\n\r\n29-11-2022 : Heeft initatie gehouden met de klant. De opdracht is duidelijk, de klant weet wat hij ongeveer kan verwachten. Ruben is bezig met examen offerte, deze verstuurd hij vandaag nog. Dit is zijn eerste week van zijn project. \r\n\r\n7-12-2022: Hij is momenteel bezig met documentatie en gaat beginnen met het realiseren van zijn user stories. Hij heeft voor vandaag nog een meeting staan met de klant waarbij ze de documentatie nog doornemen en wat dingen bespreken over de betalingsproviderl.  ', 'Software', 'ES-2022-48', 'Dylan', '07/12/2022 11:29'),
(125, 'NagelStudio', 'Katja Willemse ', 'Natasha Willemse ', 'Normaal', 'Wouter Mahu', '+31 6 811 180 70', 'natashawillemse@hotmail.com', 'Katja Willemse', 'Katja Willemse en Nick Mulders', 'Bezig', 'Ik wil een logo en huisstijl. Ook een prijslijst en huisregels om op insta te posten.\r\n\r\n7-12-2022: Ze heeft initatie gesprek gehad, ze heeft concepten gemaakt. Vandaag om 12 uur heeft ze concept pitch. Bij de pitch kan er geen coach bij zitten dus het gesprek wordt opgenomen. ', 'Media', 'EM-2022-49', 'Dylan', '07/12/2022 11:36'),
(126, 'Uitleensysteem (examen)', '-', 'Vincent Brunings', 'Normaal', 'Cees-Jan Berman', '+31 6 485 195 43', 'vbrunings@Scalda.nl', '-', '-', 'Initiatie', 'Beste, Ik zou graag een systeem willen waarbij wij als docenten (of aangewezen studenten) materialen zoals camera\'s, iPads, lampen e.d.m. kunnen uitlenen aan studenten. Het doel is dat het inzichtelijk is wie bepaalde materialen hebben geleend en dat we kunnen terugzien wie spullen geleend hebben voor het geval we iets missen bijvoorbeeld. (examenproject)', 'Software', 'ES-2022-50', 'Amber', '07/12/2022 09:41'),
(127, 'Website Steba', '-', 'Pascal de Badts', 'Normaal', 'Cees-Jan Berman', '+31 6 506 717 20', 'stebamode@hetnet.nl', '-', 'Amber Middelkamp & Tristan Verschueren', 'Initiatie', 'Wij hebben een nieuwe, website nodig... die we evt. eenvoudig zelf kunnen onderhouden.', 'Software', 'ES-2022-51', 'Amber', '07/12/2022 10:09'),
(128, 'Betalingen Introductieweek', 'Norah Blaauw', 'IVS Financieel', 'Normaal', 'Tristan Verschueren', '-', '-', 'Norah Blaauw', '-', 'Bezig', 'De betalingen moeten geregeld worden voor de eerste jaars studenten die nog niet hebben betaald voor de introductieweek moeten betalen en de betalingen van de vormgevers die wel binnen zijn gekomen moeten van Scalda naar IVS overgeboekt worden.', 'Media & Software', 'MANAGEMENT', 'Tristan', '30/11/2022 11:29'),
(129, 'Marketingplan IVS', 'Dylan Bouwhuizen', 'IVS Marketing', 'Normaal', 'Tristan Verschueren', '-', '-', 'Marketing', '-', 'Bezig', 'Er moet een marketingplan voor IVS komen.', 'Media & Software', 'MANAGEMENT', 'Tristan', '30/11/2022 11:31'),
(130, 'Boekhouding IVS', 'Norah Blaauw', 'IVS Financieel', 'Normaal', 'Tristan Verschueren', '-', '-', 'Norah Blaauw', '-', 'In Afwachting', 'Er moet onderzoek gedaan worden naar een boekhoudsysteem.', 'Media & Software', 'MANAGEMENT', 'Tristan', '30/11/2022 11:33'),
(131, 'Lego League wervingsfilm', 'Rick Wagenaar', 'Paulien van â€™t Westeinde', 'Normaal', 'Wouter Mahu', '06-20661426', 'paulien@huisvandetechniek.nl', '-', 'Rick Wagenaar', 'Bezig', 'Vrijdag 16 december a.s. zal er in de aula (en wat lokalen) van Scalda Terneuzen een regiofinale plaatsvinden van First Lego League.\r\n \r\nFotoâ€™s en video opnames maken van het evenement, vervolgens een filmpje maken van de beelden met als doel om voor volgend jaar nieuwe teams te werven.', 'Media', 'MANAGEMENT', 'Woutermahu', '07/12/2022 14:20');
INSERT INTO `tickets` (`id`, `projectnaam`, `klant`, `email`, `project_status`, `projectcoach`, `indiener`, `beheerder`, `ticketomschrijving`, `ticketnummer`, `prio`, `korte`) VALUES
(1, 'IVS Site Ticket aanvraag', 'Ruben Struijlaart', 'rstruijlaart@student.scalda.nl', 'Afgerond', '-', 'Ruben Struijlaart', 'Korben de Vos', 'Er is op het moment geen manier voor bestaande klanten om \r\ntickets in te dienen zonder apart contact met ons op te nemen, ik wil dat hier een apart formulier voor komt op de site zodat wij netjes alle tickets binnen krijgen. en dat klanten een automatisch een reactie terug krijgen', 'IS-2021-001', 'Normaal', '-'),
(3, 'ZAOS', 'Willem Poppe', 'poppe@zaos.nl', 'Afgerond', '-', 'Aaron Wakefield', 'Yari Morcus', '• Geboortedatum, studentennummer en mobiele telefoonnummer graag nog als extra velden die ik kan invullen bij de LIO\r\n\r\n• Spelfout in \'code bekostiging\'\r\n\r\n• LIO\'s moeten ook kunnen worden verwijderd, zeker nu in de testfase, dus graag veld \'Delete\' toevoegen.\r\n\r\n• Het lukt me nog niet om een nieuw aangemaakte LIO ook aan een opleidingslocatie te koppelen. Als ik op \'LIO beheren\' klik (bijv. Vivien Melis) en de door mij aangemaakte opleidingslocatie (CSW v/d Perre) selecteer en dit bevestig blijft dit niet staan. Ook het leerjaar blijft verspringen naar jaar 4, terwijl ik steeds jaar 3 selecteer.\r\n\r\n• Wat wordt er bedoeld met het begrip \'Status\'? Wat voor \'status\' zou ik daar kunnen invoeren?', 'ES-2021-003', 'Normaal', '-'),
(4, 'ZAOS', 'Willem Poppe', 'poppe@zaos.nl', 'Afgerond', '-', 'Willem Poppe', 'Jeffrey Scheffers', 'Op het actiescherm staat een aantal blokjes\r\n•	De blokjes zouden dezelfde grootte krijgen. \r\n•	Het woord beheren kan weg, want dat is overal aan de orde. \r\n•	LiO moet het eerste blokje zijn: dat is de belangrijkste. \r\n•	Stageplek beheren moet zijn : aantal plaatsen', 'ES-2021-004', 'Normaal', '-'),
(6, 'IVS Site', 'Ruben Struijlaart', 'rstruijlaart@student.scalda.nl', 'Afgerond', '-', 'Ruben Struijlaart', 'Jeffrey Scheffers', 'Bij het meeloop formulier moet het veldje leeftijd weg.', 'IS-2022-002', 'Normaal', '-'),
(9, 'VVEI Zeeland', 'Jeanneke Niewenhuijse', 'Jeanneke@itngroep.nl', 'Afgerond', '-', 'Jeanneke Niewenhuijse', 'Miko', 'Het contactformulier op de website www.vveizeeland.nl werkt niet meer. Er komt een foutmelding bij het versturen van het formulier. ', 'ES-2022-05', 'Hoog', 'contactformulier werkt niet meer'),
(10, 'VVEI Zeeland', 'Jeanneke Niewenhuijse', 'Jeanneke@itngroep.nl', 'Bezig', '-', 'Jeanneke Niewenhuijse', 'Jaimy Zegers', 'We zouden graag bij het klikken op de logo\'s op de pagina \'vrienden op de websites van deze vrienden uit willen komen.', 'ES-2022-06', 'Hoog', 'foto linkjes maken'),
(11, 'VVEI Zeeland', 'Jeanneke Niewenhuijse', 'Jeanneke@itngroep.nl', 'Bezig', '-', 'Jeanneke Niewenhuijse', 'Jaimy Zegers', 'De homepagina bestaat nu uit 1 vaste foto. We zouden graag een slide willen van deze foto, zodat er meerdere foto\'s zichtbaar zijn. We zouden deze ook zelf willen wijzigen af en toe. Is dat mogelijk?', 'ES-2022-07', 'Hoog', 'homepage slideshow'),
(12, 'IVS Templates website', 'Tristan Verschueren', '227967@student.scalda.nl', 'Afgerond', 'Gerhard', 'Sander Bruggeman', 'JoÃ«l Schout', 'Ik zie op de template website van IVS een bugje.\r\nIn de toggle voor de dark mode staat vreemde tekst\r\ndit zou een maantje en een zonnetje moeten worden\r\n', 'IS-2022-08', 'Normaal', '-'),
(14, 'IVS Templates website', 'Tristan Verschueren', 'tverschueren@student.scalda.nl', 'Afgerond', '-', 'Ruben Struijlaart', 'Korben de Vos', 'Op de IVS template site is het dark/light icoontje gebroken als hij op light mode staat is het icoontje geel en staat er een - achter.', 'ES-2022-09', 'Normaal', 'dark/light icoontje gebroken'),
(15, 'IVS Website', 'Tristan Verschueren', 'tverschueren@student.scalda.nl', 'Afgerond', '-', 'Ruben Strijlaart', '-', '', 'IS-2022-10', 'Normaal', 'facebook icoontje footer'),
(17, 'Scharretjoe', 'Rudolf Meijer', 'rudolfmeijer46@gmail.com', 'Afgerond', '-', 'Rudolf Meijer', 'Mathieu Heyndrickx', 'Ik ben sinds kort webmaster van het Smartlappenkoor \"Scharretjoe\". In 2020 is voor ons door IVS een website gemaakt, www.scharretjoe.nl. Ter informatie voeg ik de gebruiksaanwijzing bij, die ons toen is bijgeleverd. Het is mij niet duidelijk of er vÃ³Ã³r mijn bemoeienis ooit iets gewijzig is aan de site zoals die was opgeleverd. Omdat het koor recent nogal wat wijzigingen heeft ondergaan is er nu behoefte aan een update. Dat reken ik tot mijn taak. Om die taak naar behoren te vervullen heb ik wat informatie nodig die ik niet in de gebruiksaanwijzing, of in de back-end, kon vinden.\r\n\r\n1. Ik probeerde het password bij \"admin\" te wijzigen, maar slaagde daar niet in. Tevens probeerde ik het administratie e-mail adres (ingesteld bij \"Instellingen/Algemeen\") door mijn eigen e-mail adres te vervangen, maar dat bleef hangen op \"Er is een wachtende wijziging van het beheerders e-mailadres naar ...  Tenslotte heb ik een nieuwe gebruikersnaam en password ingevoerd en die gebruik ik nu; maar dat is onbevredigend.\r\n2. Ik begrijp uit de gebruiksaanwijzing dat wijzigingen kunnen worden bewerkstelligd via \"Weergave/Customizer\". Dat is een aanpak die ik niet ken van andere Wordpress sites -- ik ben ook webmaster van Museum Panorama Walcheren (www.panoramawalcheren.nl) en in het back-end van die site gebruik ik de optie \"Pagina\'s\", een optie die overigens ook bij de Scharretjoe site aanwezig is, maar volgens de gebruiksaanwijzing niet gebruikt wordt.\r\n3. Wellicht als consequentie van de gekozen opzet vind ik het moeilijk om een aantal elementen van de website terug te vinden in het back-end.\r\n    Ten eerste: \"CafÃ© de Concurrent\" en \"Accordeonist Monty\", beiden worden getoond direct onder het onderdeel \"Dirigent\", dat ik wel terug vind wia \"Weergave/Customizer\". Deze twee elementen moeten worden vervangen, maar ik zou niet weten hoe.\r\n    Ten tweede: De tekst in de footer \"Smartlappenkoor Scharretjoe is opgericht in 2007 en bestaat uit Â± 70 enthousiaste mannen en vrouwen...\" Ook deze moet gewijzigd worden en is niet terug te vinden.\r\n4. De sectie \"Repertoire/Contact\" bestaat uit drie kolommen, waarvan de derde als \"Links\" bestempeld is. Dat heeft invloed op de formattering van de inhoud. Ik wil dat wijzigen, maar zie niet hoe.\r\n5, Ik wil een nieuwe, wat langere, tekst apart opslaan en daarnaar verwijzen vanaf de hoofdpagina. Hoe moet dat in deze opzet?\r\n\r\nUit het bovenstaande kun je opmaken dat wij de indeling van de site niet willen omgooien, maar alleen de nodige updates willen doen. Ik hoop spoedig van jullie uitsluitsel te krijgen of dat inderdaad mogelijk is.\r\n\r\n\r\n(vraag aan ruben struijlaart voor handleiding)\r\n', 'IS-2022-12', 'Normaal', 'Stuk'),
(18, 'IVS PMS', 'Tristan Verschueren', '227967@student.scalda.nl', 'Ingediend', '-', 'Tristan Verschueren', '-', 'Bij het gebruiken van de PMS in Chrome op MacOS bugt de styling waardoor het onmogelijk is om de PMS te gebruiken op Chrome op MacOS. Als er wordt gescrold op de projecten pagina of ticketspagina dan verdwijnt een deel van de projecten / tickets of soms zelfs de hele pagina.\r\n\r\nIk kan zelf geen oplossing vinden voor dit probleem en het is ook heel specifiek alleen op Chrome op Mac.', 'IS-2022-13', 'Hoog', 'Chrome MacOS CSS bug'),
(19, 'IVS Website', 'Tristan Verschueren', '227967@student.scalda.nl', 'Afgerond', '-', 'Vincent Brunings', 'Rick van Tilburg', 'Op de website van IVS staat er steeds de opleiding mediavormgeving, maar het is mediavormgever', 'IS-2022-14', 'Normaal', 'Tekst niet correct'),
(20, 'IVS Website', 'Tristan Verschueren', '227967@student.scalda.nl', 'Afgerond', '-', 'Tristan Verschueren', 'Mathieu Heyndrickx', 'Er mist een favicon op de website van IVS.\r\n\r\nFavicon moet aangeleverd worden door Tristan.', 'IS-2022-15', 'Hoog', 'Favicon mist'),
(21, 'IVS Website', 'Tristan Verschueren', '227967@student.scalda.nl', 'Ingediend', '-', 'Tristan Verschueren', 'Nick Kroezen', 'De website is niet beveiligd als ik deze benader zonder er www of https voor te zetten', 'IS-2022-16', 'Normaal', 'Website niet beveiligd'),
(22, 'IVS Templates website', 'Tristan Verschueren', '227967@student.scalda.nl', 'Ingediend', '-', 'Vincent Brunings', '-', 'Op de templatesite mist het nieuwe Kwalificatiedossier.', 'IS-2022-17', 'Normaal', 'Nieuw kwalificatiedossier SD mist'),
(23, 'IVS Templates website', 'Tristan Verschueren', '227967@student.scalda.nl', 'Ingediend', '-', 'Vincent Brunings', '-', 'Op de templatesite mist het Kwalificatiedossier voor MV\r\n\r\nKwalificatiedossier is online te vinden.', 'IS-2022-18', 'Normaal', 'Kwalificatiedossier voor MV mist'),
(24, 'IVS Templates website', 'Tristan Verschueren', '227967@student.scalda.nl', 'Afgerond', '-', 'Vincent Brunings', 'Ruben Struijlaart', 'Favicon op template website mist op de IVS template website.\r\n\r\nFavicon moet worden aangeleverd door Tristan.', 'IS-2022-19', 'Normaal', 'Template website heeft geen favicon'),
(25, 'IVS Website', 'Tristan Verschueren', '227967@student.scalda.nl', 'Ingediend', '-', 'Vincent Brunings', '-', 'De tooltip op de prijs per sprint is goed bedacht, maar verschijnt in mijn ogen veel te onverwachts.', 'IS-2022-20', 'Normaal', 'Tooltip uitleg sprint duidelijker maken'),
(26, 'PUUR Zeeland', 'Petra Jeras', 'petrajeras1@gmail.com', 'Ingediend', '-', 'Petra Jeras', '-', 'Op de contactpagina staat 2x de privacy verklaring, kunnen jullie ervoor zorgen dat deze onder de kaart verdwijnt en onder verzenden erop blijft staan?\r\n\r\nwww.puurzeeland.com', 'IS-2022-21', 'Normaal', 'Dubbele gegevens op contactpagina'),
(27, 'PUUR Zeeland', 'Petra Jeras', 'petrajeras1@gmail.com', 'Ingediend', '-', 'Petra Jeras', '-', 'de uitlijning de titel `Vraag een offerte aan` deze tekst staat teveel naar links.\r\n\r\nwww.puurzeeland.com', 'IS-2022-22', 'Hoog', 'Uitlijning van een titel verkeerd');
